def _load_job_details_cache_json() -> List[Dict[str, Any]]:
    try:
        if not os.path.exists(JOB_DETAILS_CACHE_FILE):
            return []
        with open(JOB_DETAILS_CACHE_FILE, "r", encoding="utf-8-sig") as f:
            raw = json.load(f)
        rows = raw.get("entries") if isinstance(raw, dict) else raw
        return [row for row in (rows or []) if isinstance(row, dict) and isinstance(row.get("payload"), dict)]
    except Exception:
        return []


def _save_job_details_cache_json(rows: List[Dict[str, Any]]) -> bool:
    try:
        os.makedirs(DATABASE_DIR, exist_ok=True)
        payload = {
            "updated_at_utc": datetime.now(timezone.utc).isoformat(),
            # Job responses can be fairly rich. Keep a bounded offline working
            # set so this fallback never grows with the lifetime of the Pi.
            "entries": list(rows or [])[-100:],
        }
        tmp = f"{JOB_DETAILS_CACHE_FILE}.tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump(payload, f, ensure_ascii=False, indent=2, default=str)
        os.replace(tmp, JOB_DETAILS_CACHE_FILE)
        return True
    except Exception:
        try:
            if os.path.exists(f"{JOB_DETAILS_CACHE_FILE}.tmp"):
                os.remove(f"{JOB_DETAILS_CACHE_FILE}.tmp")
        except Exception:
            pass
        return False


