def _load_sql_config() -> Dict[str, Any]:
    cfg: Dict[str, Any] = {
        # Raspberry Pi clients communicate through the server API. Direct SQL
        # is opt-in for legacy installations and must never require shipping
        # server database credentials with a normal client deployment.
        "enabled": False,
        "host": "localhost",
        "port": 3306,
        "database": "rpimachineapp_db",
        "user": "rpimachine_user",
        "password": "0t1docmtl$tm",
        "connect_timeout": 5,
    }
    try:
        if os.path.exists(SQL_CONFIG_FILE):
            with open(SQL_CONFIG_FILE, "r", encoding="utf-8-sig") as f:
                raw = json.load(f)
            if isinstance(raw, dict):
                cfg.update(raw)
    except Exception:
        pass
    try:
        cfg["port"] = int(cfg.get("port", 3306) or 3306)
    except Exception:
        cfg["port"] = 3306
    return cfg


def _sql_conn():
    if pymysql is None:
        print("[SQL] PyMySQL is not installed. MySQL features are unavailable.")
        return None
    cfg = _load_sql_config()
    if not cfg.get("enabled"):
        print("[SQL] SQL is disabled in configuration.")
        return None
    try:
        return pymysql.connect(
            host=str(cfg.get("host", "localhost")),
            port=int(cfg.get("port", 3306)),
            user=str(cfg.get("user", "")),
            password=str(cfg.get("password", "")),
            database=str(cfg.get("database", "")),
            charset="utf8mb4",
            cursorclass=DictCursor,
            autocommit=False,
            connect_timeout=int(cfg.get("connect_timeout", 5) or 5),
        )
    except Exception as e:
        print(f"[SQL] Connection failed: {e}")
        return None


def _load_user_qr_profiles_sql() -> List[Dict[str, Any]]:
    conn = _sql_conn()
    if conn is None:
        return []
    try:
        out: List[Dict[str, Any]] = []
        with conn.cursor() as cur:
            cur.execute("SELECT `raw_json` FROM `user_qr_profiles` ORDER BY `id` ASC")
            for row in cur.fetchall() or []:
                raw = row.get("raw_json") if isinstance(row, dict) else None
                item = raw if isinstance(raw, dict) else None
                if item is None and isinstance(raw, str):
                    try:
                        item = json.loads(raw)
                    except Exception:
                        item = None
                if isinstance(item, dict):
                    out.append(item)
        return out
    except Exception as e:
        print(f"[SQL] Failed to load user QR profiles: {e}")
        return []
    finally:
        try:
            conn.close()
        except Exception:
            pass


def _load_active_sessions_sql() -> Dict[str, Any]:
    conn = _sql_conn()
    if conn is None:
        return {}
    try:
        out: Dict[str, Any] = {}
        with conn.cursor() as cur:
            cur.execute("SELECT `machine_code`, `raw_json` FROM `active_machine_sessions` ORDER BY `machine_code` ASC")
            for row in cur.fetchall() or []:
                machine_code = str(row.get("machine_code") or "").strip()
                raw = row.get("raw_json")
                item = raw if isinstance(raw, dict) else None
                if item is None and isinstance(raw, str):
                    try:
                        parsed = json.loads(raw)
                    except Exception:
                        parsed = None
                    if isinstance(parsed, dict):
                        item = parsed
                if machine_code and isinstance(item, dict):
                    out[machine_code] = item
        return out
    except Exception:
        return {}
    finally:
        conn.close()


def _read_active_sessions_payload(path: str) -> Dict[str, Any]:
    if not os.path.exists(path):
        raise FileNotFoundError(path)
    with open(path, "r", encoding="utf-8") as f:
        loaded = json.load(f)
    return loaded if isinstance(loaded, dict) else {}


def _active_sessions_backup_path(path: str) -> str:
    return f"{path}.bak"


def _backup_active_sessions_file(path: str) -> None:
    if not os.path.exists(path):
        return
    backup_path = _active_sessions_backup_path(path)
    with open(path, "rb") as src, open(backup_path, "wb") as dst:
        dst.write(src.read())
        dst.flush()
        os.fsync(dst.fileno())


def _read_active_sessions_json_file(path: str) -> Dict[str, Any]:
    rows, _source = _read_active_sessions_json_file_with_source(path)
    return rows


def _read_active_sessions_json_file_with_source(path: str) -> tuple[Dict[str, Any], str]:
    try:
        loaded = _read_active_sessions_payload(path)
        source = "main"
    except Exception:
        try:
            loaded = _read_active_sessions_payload(_active_sessions_backup_path(path))
            source = "bak"
        except Exception:
            return {}, ""
    try:
        out: Dict[str, Any] = {}
        for machine_code, row in loaded.items():
            code = str(machine_code or "").strip()
            if code and isinstance(row, dict):
                item = dict(row)
                item["machine_code"] = str(item.get("machine_code") or code).strip()
                out[code] = item
        return out, source
    except Exception:
        return {}, ""


def _load_active_sessions_json() -> Dict[str, Any]:
    return _read_active_sessions_json_file(CLIENT_ACTIVE_MACHINE_SESSIONS_FILE)


def _save_active_sessions_json(rows: Dict[str, Any]) -> bool:
    try:
        os.makedirs(DATABASE_DIR, exist_ok=True)
        payload: Dict[str, Any] = {}
        for machine_code, row in (rows or {}).items():
            code = str(machine_code or "").strip()
            if code and isinstance(row, dict):
                item = dict(row)
                item["machine_code"] = str(item.get("machine_code") or code).strip()
                payload[code] = item
        target = CLIENT_ACTIVE_MACHINE_SESSIONS_FILE
        tmp = f"{target}.tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump(payload, f, ensure_ascii=False, indent=2)
            f.flush()
            os.fsync(f.fileno())
        _backup_active_sessions_file(target)
        os.replace(tmp, target)
        return True
    except Exception as e:
        print(f"[JSON] Active session save failed: {e}")
        return False


def _upsert_active_session_json(row: Dict[str, Any]) -> bool:
    machine_code = str((row or {}).get("machine_code") or "").strip()
    if not machine_code:
        return False
    rows = _load_active_sessions_json()
    payload = dict(row or {})
    payload["machine_code"] = machine_code
    rows[machine_code] = payload
    return _save_active_sessions_json(rows)


def _delete_active_session_json(machine_code: Optional[str]) -> bool:
    code = str(machine_code or "").strip()
    if not code:
        return False
    rows = _load_active_sessions_json()
    if code in rows:
        rows.pop(code, None)
        return _save_active_sessions_json(rows)
    return True


def _load_confirmed_server_sessions_json() -> Dict[str, Any]:
    return _read_active_sessions_json_file(SERVER_CONFIRMED_SESSIONS_FILE)


def _upsert_confirmed_server_session_json(row: Dict[str, Any]) -> bool:
    machine_code = str((row or {}).get("machine_code") or "").strip()
    if not machine_code:
        return False
    rows = _load_confirmed_server_sessions_json()
    payload = dict(row or {})
    payload["machine_code"] = machine_code
    previous = rows.get(machine_code) if isinstance(rows.get(machine_code), dict) else {}
    previous_comparable = {
        key: value for key, value in previous.items() if key != "_confirmed_at_utc"
    }
    if previous_comparable == payload:
        return True
    payload["_confirmed_at_utc"] = datetime.now(timezone.utc).isoformat()
    rows[machine_code] = payload
    try:
        os.makedirs(DATABASE_DIR, exist_ok=True)
        target = SERVER_CONFIRMED_SESSIONS_FILE
        tmp = f"{target}.tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump(rows, f, ensure_ascii=False, indent=2)
            f.flush()
            os.fsync(f.fileno())
        _backup_active_sessions_file(target)
        os.replace(tmp, target)
        return True
    except Exception:
        return False


def _load_server_event_queue_json() -> List[Dict[str, Any]]:
    try:
        if not os.path.exists(SERVER_EVENT_QUEUE_FILE):
            return []
        with open(SERVER_EVENT_QUEUE_FILE, "r", encoding="utf-8") as f:
            rows = json.load(f)
        loaded = [row for row in (rows or []) if isinstance(row, dict) and isinstance(row.get("payload"), dict)]
        clean = _trim_server_event_queue_rows(loaded)
        if len(clean) != len(loaded):
            _save_server_event_queue_json(clean)
        return clean
    except Exception:
        return []


def _server_event_queue_type(row: Dict[str, Any]) -> str:
    payload = row.get("payload") if isinstance(row, dict) else {}
    event = payload.get("event") if isinstance(payload, dict) else {}
    if isinstance(event, dict):
        return str(event.get("type") or "").strip().upper()
    return ""


def _server_event_queue_row_is_defective(row: Dict[str, Any]) -> bool:
    """Reject payloads that the server cannot safely apply or acknowledge."""
    if not isinstance(row, dict):
        return True
    payload = row.get("payload")
    if not isinstance(payload, dict):
        return True
    client_id = str(payload.get("client_id") or "").strip()
    machine_code = str(payload.get("machine_code") or "").strip()
    event = payload.get("event")
    if not client_id or not machine_code or not isinstance(event, dict):
        return True
    event_type = str(event.get("type") or "").strip().upper()
    if not event_type:
        return True
    if event_type == "SESSION_SYNC" and not isinstance(event.get("session_snapshot"), dict):
        return True
    if event_type in ("FINISH_SHIFT", "FINISH_JOB") and not isinstance(event.get("finished_job"), dict):
        return True
    if event_type == "PACK":
        try:
            if int(event.get("pack_qty", 1) or 1) <= 0 or int(event.get("qty", 0) or 0) < 0:
                return True
        except (TypeError, ValueError):
            return True
    return False


def _server_event_queue_row_is_stale(row: Dict[str, Any]) -> bool:
    payload = row.get("payload") if isinstance(row, dict) else {}
    if isinstance(payload, dict) and int(payload.get("sync_protocol_requested") or 0) >= SERVER_SYNC_PROTOCOL_VERSION:
        # Protocol 2 events are the durable mutation log. They may only leave
        # the queue after the server acknowledges their unique event ID.
        return False
    created_raw = str((row or {}).get("created_at_utc") or "").strip()
    if not created_raw:
        return False
    try:
        created_at = datetime.fromisoformat(created_raw.replace("Z", "+00:00"))
        if created_at.tzinfo is None:
            created_at = created_at.replace(tzinfo=timezone.utc)
        age_seconds = max(
            0.0,
            (datetime.now(timezone.utc) - created_at.astimezone(timezone.utc)).total_seconds(),
        )
        return age_seconds > float(SERVER_EVENT_QUEUE_MAX_AGE_SECONDS)
    except Exception:
        return False


def _trim_server_event_queue_rows(rows: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    clean: List[Dict[str, Any]] = []
    latest_session_sync: Dict[tuple, Dict[str, Any]] = {}
    finish_shift_indexes: Dict[tuple, int] = {}
    for row in rows or []:
        if _server_event_queue_row_is_defective(row):
            continue
        if _server_event_queue_row_is_stale(row):
            continue
        # A PACK (and most other events) is already a small delta. Persisting a
        # full session snapshot with every delta makes the JSON queue grow
        # quadratically as scan history increases. SESSION_SYNC is the sole
        # durable recovery snapshot; all other events remain compact deltas.
        payload = dict(row.get("payload") or {})
        event = dict(payload.get("event") or {})
        event_type = str(event.get("type") or "").strip().upper()
        if event_type != "SESSION_SYNC":
            event.pop("session_snapshot", None)
        payload["event"] = event
        compact_row = dict(row)
        compact_row["payload"] = payload

        if int(payload.get("sync_protocol_requested") or 0) >= SERVER_SYNC_PROTOCOL_VERSION:
            # Preserve protocol 2 in its exact original order. Server-side
            # event-ID deduplication makes retries safe without coalescing.
            clean.append(compact_row)
            continue

        identity = (
            str(payload.get("client_id") or "").strip(),
            str(payload.get("machine_code") or "").strip(),
        )
        if event_type == "SESSION_SYNC":
            latest_session_sync[identity] = compact_row
            continue
        if event_type == "FINISH_SHIFT":
            finished = event.get("finished_job") if isinstance(event.get("finished_job"), dict) else {}
            shift_key = identity + (
                str(finished.get("job_code") or payload.get("job_code") or "").strip(),
                str(finished.get("operator_id") or payload.get("operator_id") or "").strip(),
                str(finished.get("finished_at_utc") or finished.get("shift_finished_at_utc") or "").strip(),
            )
            if shift_key in finish_shift_indexes:
                clean[finish_shift_indexes[shift_key]] = compact_row
                continue
            finish_shift_indexes[shift_key] = len(clean)
        clean.append(compact_row)

    # Keep only the newest recovery snapshot for each client/machine. Appending
    # it last ensures the server sees all queued deltas before final state repair.
    clean.extend(latest_session_sync.values())
    if any(
        int(((row.get("payload") or {}).get("sync_protocol_requested") or 0)) >= SERVER_SYNC_PROTOCOL_VERSION
        for row in clean
        if isinstance(row, dict) and isinstance(row.get("payload"), dict)
    ):
        return clean
    max_rows = max(50, int(SERVER_EVENT_QUEUE_DISK_MAX_ENTRIES or 5000))
    if len(clean) <= max_rows:
        return clean
    return clean[-max_rows:]


def _save_server_event_queue_json(rows: List[Dict[str, Any]]) -> bool:
    try:
        os.makedirs(DATABASE_DIR, exist_ok=True)
        # The queue is the offline source of truth.  Write it atomically so a
        # power loss cannot leave a partially-written JSON file and discard
        # scans that have not reached the server yet.
        tmp = f"{SERVER_EVENT_QUEUE_FILE}.tmp"
        payload = _trim_server_event_queue_rows(rows)
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump(payload, f, ensure_ascii=False, indent=2)
            f.flush()
            os.fsync(f.fileno())
        os.replace(tmp, SERVER_EVENT_QUEUE_FILE)
        return True
    except Exception:
        try:
            if os.path.exists(f"{SERVER_EVENT_QUEUE_FILE}.tmp"):
                os.remove(f"{SERVER_EVENT_QUEUE_FILE}.tmp")
        except Exception:
            pass
        return False


def _load_scanned_pack_qr_keys_json() -> Dict[str, Dict[str, Any]]:
    try:
        if not os.path.exists(SCANNED_PACK_QR_KEYS_FILE):
            return {}
        with open(SCANNED_PACK_QR_KEYS_FILE, "r", encoding="utf-8") as f:
            rows = json.load(f)
        if not isinstance(rows, dict):
            return {}
        payload = {
            str(key): dict(value)
            for key, value in rows.items()
            if str(key).strip() and isinstance(value, dict)
        }
        return payload
    except Exception:
        return {}


def _save_scanned_pack_qr_keys_json(rows: Dict[str, Dict[str, Any]]) -> bool:
    try:
        os.makedirs(DATABASE_DIR, exist_ok=True)
        tmp = f"{SCANNED_PACK_QR_KEYS_FILE}.tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump(dict(rows or {}), f, ensure_ascii=False, indent=2)
            f.flush()
            os.fsync(f.fileno())
        os.replace(tmp, SCANNED_PACK_QR_KEYS_FILE)
        return True
    except Exception:
        return False


def _upsert_scanned_pack_qr_key(key: str, row: Dict[str, Any]) -> bool:
    k = str(key or "").strip()
    if not k:
        return False
    rows = _load_scanned_pack_qr_keys_json()
    existing = rows.get(k)
    if isinstance(existing, dict):
        return True
    rows[k] = dict(row or {})
    rows[k]["key"] = k
    return _save_scanned_pack_qr_keys_json(rows)


def _delete_scanned_pack_qr_key(key: str) -> bool:
    k = str(key or "").strip()
    if not k:
        return False
    rows = _load_scanned_pack_qr_keys_json()
    if k not in rows:
        return True
    rows.pop(k, None)
    return _save_scanned_pack_qr_keys_json(rows)


