    def _position_floating_pack_qr_panel(self):
        if not hasattr(self, "floatingPackQrPanel") or self.floatingPackQrPanel is None:
            return
        parent = self.floatingPackQrPanel.parentWidget()
        if parent is not None and parent is getattr(self, "partsHistoryOuter", None):
            margin = 8
            w = max(1, int(parent.width()) - (margin * 2))
            h = max(1, int(parent.height()) - (margin * 2))
            self.floatingPackQrPanel.setGeometry(margin, margin, w, h)
            self._fit_floating_pack_qr_image()
            return
        margin = 12
        w = min(280, max(1, self.width() - (margin * 2)))
        h = min(350, max(1, self.height() - (margin * 2)))
        x = max(margin, self.width() - w - margin)
        y = min(
            max(margin, int(self.height() * 0.42)),
            max(margin, self.height() - h - margin),
        )
        self.floatingPackQrPanel.setGeometry(x, y, w, h)
        self._fit_floating_pack_qr_image()

    def _fit_floating_pack_qr_image(self):
        """Keep the complete QR square inside its panel at every UI scale."""
        if not hasattr(self, "floatingPackQrImage") or self.floatingPackQrImage is None:
            return
        panel_w = max(1, int(self.floatingPackQrPanel.width()))
        panel_h = max(1, int(self.floatingPackQrPanel.height()))
        # Title, metadata, layout margins, and spacing require about 68 px.
        qr_side = max(1, min(280, panel_w - 24, panel_h - 68))
        self.floatingPackQrImage.setFixedSize(qr_side, qr_side)
        payload = str(getattr(self, "_floating_pack_qr_payload", "") or "").strip()
        if payload and qr_side != int(getattr(self, "_floating_pack_qr_render_size", 0) or 0):
            pm = self._qr_pixmap_for_payload(payload, qr_side)
            if not pm.isNull():
                self.floatingPackQrImage.setPixmap(pm)
                self.floatingPackQrImage.setText("")
                self._floating_pack_qr_render_size = qr_side

