    def _save_active_session_snapshot(self, force: bool = False):
        s = self.state
        machine_code = str(s.machine_code or "").strip()
        if not machine_code:
            return
        self._active_session_snapshot_deferred_pending = False
        snapshot = self._state_to_active_snapshot()
        try:
            serialized = json.dumps(snapshot, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
        except Exception:
            serialized = ""
        if not force and serialized and serialized == self._last_active_session_snapshot_serialized:
            return
        # Disk I/O grows with the session histories and must not block the Qt
        # scanner callback.  The persistence worker coalesces older snapshots
        # while preserving the newest complete state.
        self._enqueue_active_session_file_persist({"op": "upsert", "snapshot": snapshot})
        if serialized:
            self._last_active_session_snapshot_serialized = serialized
        self._trigger_active_session_sql_sync(force=False)

    def _schedule_active_session_snapshot_save(self, delay_ms: int = 250):
        if not str(self.state.machine_code or "").strip():
            return
        self._active_session_snapshot_deferred_pending = True
        if hasattr(self, "activeSessionDeferredSaveTimer") and self.activeSessionDeferredSaveTimer is not None:
            self.activeSessionDeferredSaveTimer.start(max(0, int(delay_ms or 0)))
        else:
            self._save_active_session_snapshot(force=False)

    def _flush_deferred_active_session_snapshot(self):
        if not bool(getattr(self, "_active_session_snapshot_deferred_pending", False)):
            return
        self._save_active_session_snapshot(force=False)

    def _autosave_active_session_snapshot(self):
        s = self.state
        if not str(s.machine_code or "").strip():
            return
        self._save_active_session_snapshot(force=False)

    def _snapshot_is_recoverable(self, snap: Dict[str, Any]) -> bool:
        if not isinstance(snap, dict):
            return False
        if not str(snap.get("machine_code") or "").strip():
            return False
        if str(snap.get("job_code") or snap.get("job_name") or snap.get("operator_id") or "").strip():
            return True
        numeric_keys = (
            "pack_count",
            "pack_total",
            "good_total",
            "butal_total",
            "reject_total",
            "raw_sacks_count",
            "startup_reject_total",
            "no_shot_total",
        )
        for key in numeric_keys:
            try:
                if int(float(snap.get(key) or 0)) > 0:
                    return True
            except Exception:
                pass
        list_keys = (
            "product_pack_history_logs",
            "raw_material_logs",
            "raw_material_scans",
            "butal_scan_logs",
            "reject_review_logs",
            "operator_shift_logs",
            "machine_counter_overwrite_logs",
        )
        if any(isinstance(snap.get(key), list) and len(snap.get(key) or []) > 0 for key in list_keys):
            return True
        flag_keys = (
            "waiting_reject_reason",
            "waiting_production_report_reason",
            "waiting_downtime_start_maintenance",
            "waiting_pdr_maintenance_reason",
            "waiting_downtime_end_maintenance",
            "waiting_maintenance_qr",
            "waiting_supervisor_qr",
            "waiting_operator_downtime_confirm",
            "downtime_active",
            "waiting_initial_cycle_time_input",
            "waiting_initial_machine_counter_input",
            "waiting_shift_end_machine_counter_input",
            "waiting_machine_counter_overwrite_input",
            "waiting_machine_counter_overwrite_supervisor",
            "waiting_cycle_time_confirm_popup",
            "supervisor_review_open",
            "reject_review_open",
        )
        return any(bool(snap.get(key)) for key in flag_keys)

    def _snapshot_sort_key(self, snap: Dict[str, Any]) -> str:
        if not isinstance(snap, dict):
            return ""
        return str(snap.get("saved_at_utc") or snap.get("last_seen_utc") or "")

    def _snapshot_timestamp_value(self, snap: Dict[str, Any]) -> Optional[float]:
        if not isinstance(snap, dict):
            return None
        raw = str(snap.get("saved_at_utc") or snap.get("last_seen_utc") or "").strip()
        if not raw:
            return None
        try:
            dt = datetime.fromisoformat(raw.replace("Z", "+00:00"))
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=timezone.utc)
            return float(dt.timestamp())
        except Exception:
            return None

    def _snapshot_richness_score(self, snap: Dict[str, Any]) -> int:
        if not isinstance(snap, dict):
            return 0
        score = 0
        if str(snap.get("job_code") or snap.get("job_name") or "").strip():
            score += 20
        if str(snap.get("operator_id") or "").strip():
            score += 20
        list_weights = {
            "product_pack_history_logs": 8,
            "raw_material_logs": 5,
            "raw_material_scans": 3,
            "butal_scan_logs": 5,
            "reject_review_logs": 5,
            "operator_shift_logs": 4,
            "production_adjustment_logs": 4,
            "machine_counter_overwrite_logs": 5,
        }
        for key, weight in list_weights.items():
            rows = snap.get(key)
            if isinstance(rows, list):
                score += len(rows) * weight
        flag_keys = (
            "waiting_reject_reason",
            "waiting_production_report_reason",
            "waiting_downtime_start_maintenance",
            "waiting_pdr_maintenance_reason",
            "waiting_downtime_end_maintenance",
            "waiting_maintenance_qr",
            "waiting_supervisor_qr",
            "waiting_operator_downtime_confirm",
            "downtime_active",
            "waiting_initial_cycle_time_input",
            "waiting_initial_machine_counter_input",
            "waiting_shift_end_machine_counter_input",
            "waiting_cycle_time_confirm_popup",
            "supervisor_review_open",
            "reject_review_open",
        )
        score += sum(3 for key in flag_keys if bool(snap.get(key)))
        return score

    def _choose_recovery_snapshot(
        self,
        local_snap: Optional[Dict[str, Any]],
        local_source: str,
        server_snap: Optional[Dict[str, Any]],
    ) -> Optional[Dict[str, Any]]:
        local_ok = isinstance(local_snap, dict) and self._snapshot_is_recoverable(local_snap)
        server_ok = isinstance(server_snap, dict) and self._snapshot_is_recoverable(server_snap)
        if local_ok and str(local_source or "").lower() == "main":
            return local_snap
        if local_ok and not server_ok:
            return local_snap
        if server_ok and not local_ok:
            return server_snap
        if not (local_ok and server_ok):
            return None

        local_ts = self._snapshot_timestamp_value(local_snap)
        server_ts = self._snapshot_timestamp_value(server_snap)
        if local_ts is not None and server_ts is not None and abs(local_ts - server_ts) > 1.0:
            return local_snap if local_ts > server_ts else server_snap
        if local_ts is not None and server_ts is None:
            return local_snap
        if server_ts is not None and local_ts is None:
            return server_snap

        local_score = self._snapshot_richness_score(local_snap)
        server_score = self._snapshot_richness_score(server_snap)
        if server_score > local_score:
            return server_snap
        return local_snap

    def _recoverable_snapshots_from_rows(self, rows: Dict[str, Any], *, require_current_client: bool) -> List[Dict[str, Any]]:
        out: List[Dict[str, Any]] = []
        for row in (rows or {}).values():
            if not isinstance(row, dict):
                continue
            if require_current_client and not self._belongs_to_current_client(row):
                continue
            if self._snapshot_is_recoverable(row):
                out.append(row)
        out.sort(key=self._snapshot_sort_key, reverse=True)
        return out

    def _fetch_active_session_snapshot_from_server(self, machine_code: Optional[str] = None) -> Optional[Dict[str, Any]]:
        server_url = str((self.client_config or {}).get("server_url", SERVER_URL) or SERVER_URL).strip().rstrip("/")
        if not server_url:
            return None
        params: Dict[str, Any] = {}
        code = str(machine_code or "").strip()
        if code:
            # A scanned machine is an explicit handoff lookup. Do not restrict
            # it to this Pi's client_id: another interchangeable Pi may have
            # been the last terminal that saved the machine session.
            params["machine_code"] = code
        else:
            params["client_id"] = self._current_client_id()
        try:
            resp = self._request_with_ui_events(
                requests.get,
                f"{server_url}/api/active-sessions",
                params=params,
                headers={"Accept": "application/json"},
                timeout=2.5,
            )
            if resp.status_code != 200:
                return None
            payload = resp.json()
            items = payload.get("items") if isinstance(payload, dict) else None
            if not isinstance(items, list):
                return None
            snaps = [
                dict(row)
                for row in items
                if isinstance(row, dict)
                and (bool(code) or self._belongs_to_current_client(row))
                and self._snapshot_is_recoverable(row)
            ]
            snaps.sort(key=self._snapshot_sort_key, reverse=True)
            return snaps[0] if snaps else None
        except Exception as e:
            self._append_app_log("RECOVERY", f"Server active-session recovery failed: {e}")
            return None

    def _load_active_session_snapshot(self, machine_code: str) -> Optional[Dict[str, Any]]:
        code = str(machine_code or "").strip()
        if not code:
            return None
        for path in (
            CLIENT_ACTIVE_MACHINE_SESSIONS_FILE,
            _active_sessions_backup_path(CLIENT_ACTIVE_MACHINE_SESSIONS_FILE),
        ):
            rows = _read_active_sessions_json_file(path)
            snap = rows.get(code)
            if isinstance(snap, dict) and self._snapshot_is_recoverable(snap):
                return snap
        server_snap = self._fetch_active_session_snapshot_from_server(code)
        return server_snap if isinstance(server_snap, dict) and self._snapshot_is_recoverable(server_snap) else None

    def _load_local_active_session_snapshot(self, machine_code: str) -> Optional[Dict[str, Any]]:
        """Return only this client's on-device recovery data."""
        code = str(machine_code or "").strip()
        if not code:
            return None
        for path in (CLIENT_ACTIVE_MACHINE_SESSIONS_FILE, _active_sessions_backup_path(CLIENT_ACTIVE_MACHINE_SESSIONS_FILE)):
            snap = _read_active_sessions_json_file(path).get(code)
            if isinstance(snap, dict) and self._snapshot_is_recoverable(snap):
                return snap
        return None

    def _merge_matching_recovery_snapshots(self, server_snap: Dict[str, Any], local_snap: Dict[str, Any]) -> Dict[str, Any]:
        """Merge replicated copies of one job without double-counting totals.

        Client counters are cumulative, so the highest value is the safe value;
        events/logs are merged by their serialized content.
        """
        server_session_id = str(server_snap.get("production_session_id") or "").strip()
        local_session_id = str(local_snap.get("production_session_id") or "").strip()
        if server_session_id and local_session_id and server_session_id != local_session_id:
            # Never maximize counters across two runs of the same work order.
            server_ts = self._snapshot_timestamp_value(server_snap)
            local_ts = self._snapshot_timestamp_value(local_snap)
            if local_ts is not None and (server_ts is None or local_ts > server_ts):
                return dict(local_snap)
            return dict(server_snap)

        merged = dict(server_snap or {})
        merged.update(dict(local_snap or {}))
        server_pack = server_snap.get("pack_count", server_snap.get("pack_total", 0))
        local_pack = local_snap.get("pack_count", local_snap.get("pack_total", 0))
        try:
            merged_pack = max(int(server_pack or 0), int(local_pack or 0))
            merged["pack_count"] = merged_pack
            merged["pack_total"] = merged_pack
        except Exception:
            pass
        for key in ("good_total", "butal_total", "reject_total", "no_shot_total", "raw_sacks_count", "startup_reject_total"):
            try:
                merged[key] = max(int(server_snap.get(key, 0) or 0), int(local_snap.get(key, 0) or 0))
            except Exception:
                pass
        server_rejects = _canonical_reject_breakdown(server_snap.get("reject_breakdown"))
        local_rejects = _canonical_reject_breakdown(local_snap.get("reject_breakdown"))
        merged["reject_breakdown"] = {
            str(key): max(int(server_rejects.get(key, 0) or 0), int(local_rejects.get(key, 0) or 0))
            for key in set(server_rejects) | set(local_rejects)
        }
        for key in ("product_pack_history_logs", "raw_material_logs", "raw_material_scans", "butal_scan_logs", "reject_review_logs", "operator_shift_logs"):
            rows, seen = [], set()
            for row in list(server_snap.get(key) or []) + list(local_snap.get(key) or []):
                try:
                    marker = json.dumps(row, sort_keys=True, ensure_ascii=False, default=str)
                except Exception:
                    marker = repr(row)
                if marker not in seen:
                    seen.add(marker)
                    rows.append(row)
            merged[key] = rows
        linked_by_code: Dict[str, Dict[str, Any]] = {}
        linked_order: List[str] = []
        for row in list(server_snap.get("linkage_jobs") or []) + list(local_snap.get("linkage_jobs") or []):
            if not isinstance(row, dict):
                continue
            code = self._normalize_job_code(row.get("job_code"))
            if not code:
                continue
            if code not in linked_by_code:
                linked_by_code[code] = dict(row)
                linked_order.append(code)
                continue
            existing = linked_by_code[code]
            incoming = dict(row)
            existing_payload = existing.get("job_payload") if isinstance(existing.get("job_payload"), dict) else {}
            incoming_payload = incoming.get("job_payload") if isinstance(incoming.get("job_payload"), dict) else {}
            existing.update({key: value for key, value in incoming.items() if value not in (None, "", [], {})})
            existing["job_payload"] = incoming_payload or existing_payload
        merged["linkage_jobs"] = [linked_by_code[code] for code in linked_order]
        if merged["linkage_jobs"]:
            merged["linkage_enabled"] = True
            latest_linked = merged["linkage_jobs"][-1]
            merged["linkage_job_code"] = latest_linked.get("job_code")
            merged["linkage_job_name"] = latest_linked.get("job_name")
            if isinstance(latest_linked.get("job_payload"), dict):
                merged["linkage_job_payload"] = dict(latest_linked.get("job_payload") or {})
        return merged

    def _recovery_snapshot_total_score(self, snap: Dict[str, Any]) -> int:
        if not isinstance(snap, dict):
            return 0
        return (
            self._recovery_snapshot_int(snap, "pack_count", snap.get("pack_total", 0))
            + self._recovery_snapshot_int(snap, "good_total")
            + self._recovery_snapshot_int(snap, "butal_total")
            + self._recovery_snapshot_int(snap, "reject_total")
            + self._recovery_snapshot_int(snap, "startup_reject_total")
            + self._recovery_snapshot_int(snap, "no_shot_total")
            + self._recovery_snapshot_int(snap, "raw_sacks_count")
        )

    def _resolve_recovery_snapshot(
        self,
        server_snap: Optional[Dict[str, Any]],
        local_snap: Optional[Dict[str, Any]],
    ) -> Dict[str, Any]:
        if isinstance(server_snap, dict) and isinstance(local_snap, dict):
            server_job = self._normalize_job_code(server_snap.get("job_code") or server_snap.get("job_name"))
            local_job = self._normalize_job_code(local_snap.get("job_code") or local_snap.get("job_name"))
            if server_job and local_job and server_job != local_job:
                # Counts from different jobs are unrelated and must never be
                # maximized or combined. Prefer the later saved session; if a
                # timestamp is unavailable/tied, the server is authoritative
                # for an explicit machine handoff.
                server_ts = self._snapshot_timestamp_value(server_snap)
                local_ts = self._snapshot_timestamp_value(local_snap)
                if server_ts is not None and local_ts is not None:
                    return dict(local_snap if local_ts > server_ts else server_snap)
                if local_ts is not None and server_ts is None:
                    return dict(local_snap)
                return dict(server_snap)
            server_session_id = str(server_snap.get("production_session_id") or "").strip()
            local_session_id = str(local_snap.get("production_session_id") or "").strip()
            if server_session_id and local_session_id and server_session_id != local_session_id:
                server_ts = self._snapshot_timestamp_value(server_snap)
                local_ts = self._snapshot_timestamp_value(local_snap)
                if local_ts is not None and (server_ts is None or local_ts > server_ts):
                    return dict(local_snap)
                return dict(server_snap)
            server_score = self._recovery_snapshot_total_score(server_snap)
            local_score = self._recovery_snapshot_total_score(local_snap)
            if local_score > server_score:
                return self._merge_matching_recovery_snapshots(server_snap, local_snap)
            return self._merge_matching_recovery_snapshots(local_snap, server_snap)
        if isinstance(local_snap, dict):
            return local_snap
        return dict(server_snap or {})

    def _apply_acknowledged_server_session(self, server_snap: Dict[str, Any]) -> None:
        """Apply only authoritative downward adjustments during live operation.

        Higher-counter reconciliation belongs to explicit recovery/reconnect.
        Applying it after every ordinary event can resurrect a locally voided
        production scan while its correction is still travelling in the queue.
        """
        if not isinstance(server_snap, dict):
            return
        local_snap = self._state_to_active_snapshot()
        server_machine = str(server_snap.get("machine_code") or "").strip()
        local_machine = str(local_snap.get("machine_code") or "").strip()
        server_job = self._normalize_job_code(server_snap.get("job_code") or server_snap.get("job_name"))
        local_job = self._normalize_job_code(local_snap.get("job_code") or local_snap.get("job_name"))
        if not server_machine or server_machine != local_machine:
            return
        if not server_job or not local_job or server_job != local_job:
            return
        server_session_id = str(server_snap.get("production_session_id") or "").strip()
        local_session_id = str(local_snap.get("production_session_id") or "").strip()
        if server_session_id and local_session_id and server_session_id != local_session_id:
            self._append_app_log(
                "SESSION FENCE",
                f"Ignored acknowledgement for {server_session_id}; active session is {local_session_id}",
            )
            return
        ack_event_type = str(server_snap.get("_ack_event_type") or "").strip().upper()
        if bool(server_snap.get("_server_authoritative_replace")):
            # Keep optimistic local scans visible while any mutation is still
            # waiting. Once the ordered queue is empty, the returned server
            # snapshot is the one official state for this active session.
            if self._has_pending_server_mutations():
                return
            authoritative = {
                key: value for key, value in server_snap.items()
                if not str(key).startswith("_ack_") and key != "_server_authoritative_replace"
            }
            self._restore_state_from_snapshot(authoritative)
            self._refresh_ui()
            self._save_active_session_snapshot(force=True)
            return
        if ack_event_type not in {"PACK_VOID", "PRODUCT_PART_VOID", "BUTAL_VOID", "REJECT_VOID"}:
            return
        merged = dict(local_snap)
        if ack_event_type == "PACK_VOID":
            for key in ("pack_count", "pack_total", "good_total", "product_pack_history_logs"):
                if key in server_snap:
                    merged[key] = server_snap.get(key)
        elif ack_event_type == "PRODUCT_PART_VOID":
            for key in ("raw_sacks_count", "raw_material_scans", "raw_material_logs"):
                if key in server_snap:
                    merged[key] = server_snap.get(key)
        elif ack_event_type == "BUTAL_VOID":
            for key in ("butal_total", "butal_by_job"):
                if key in server_snap:
                    merged[key] = server_snap.get(key)
        elif ack_event_type == "REJECT_VOID":
            for key in ("reject_total", "startup_reject_total", "no_shot_total", "reject_breakdown"):
                if key in server_snap:
                    merged[key] = server_snap.get(key)
        self._restore_state_from_snapshot(merged)
        self._refresh_ui()
        self._save_active_session_snapshot(force=True)

    def _recovery_shift_segment_key_from_row(self, row: Dict[str, Any], base_snap: Dict[str, Any]) -> str:
        job_key = self._normalize_job_code(row.get("job_code"))
        if not job_key:
            job_key = str(row.get("job_name") or "").strip().upper()
        return "|".join([
            str(row.get("client_id") or base_snap.get("client_id") or self._current_client_id()).strip(),
            str(row.get("machine_code") or base_snap.get("machine_code") or "").strip(),
            str(row.get("operator_id") or base_snap.get("operator_id") or "").strip(),
            job_key,
        ])

    def _recovery_shift_segment_is_recoverable(self, row: Dict[str, Any]) -> bool:
        if not isinstance(row, dict):
            return False
        if not str(row.get("job_code") or row.get("job_name") or "").strip():
            return False
        reason = str(row.get("reason") or "").upper()
        if reason not in ("COLOR_CHANGE", "MOLD_CHANGE"):
            return False
        if self._recovery_snapshot_total_score(row) > 0:
            return True
        pack_logs = row.get("product_pack_history_logs")
        return isinstance(pack_logs, list) and len(pack_logs) > 0

    def _recovery_current_session_title(self, snap: Dict[str, Any]) -> str:
        return self._recovery_session_job_title(snap)

    def _recovery_shift_segment_title(self, row: Dict[str, Any], index: int) -> str:
        return self._recovery_session_job_title(row)

    def _build_recovery_session_options(
        self,
        server_snap: Optional[Dict[str, Any]],
        local_snap: Optional[Dict[str, Any]],
    ) -> List[Dict[str, Any]]:
        server_ok = isinstance(server_snap, dict) and self._snapshot_is_recoverable(server_snap)
        local_ok = isinstance(local_snap, dict) and self._snapshot_is_recoverable(local_snap)
        if not server_ok and not local_ok:
            return []

        base_snap = self._resolve_recovery_snapshot(
            server_snap if server_ok else None,
            local_snap if local_ok else None,
        )
        options: List[Dict[str, Any]] = []
        seen_segment_keys: Set[str] = set()

        if self._snapshot_is_recoverable(base_snap):
            current_key = self._recovery_shift_segment_key_from_row(base_snap, base_snap)
            options.append(
                {
                    "kind": "current",
                    "title": self._recovery_current_session_title(base_snap),
                    "snap": base_snap,
                    "display_snap": base_snap,
                    "base_snap": base_snap,
                    "segment": None,
                }
            )
            if current_key:
                seen_segment_keys.add(current_key)

        segment_rows = [
            dict(row)
            for row in (base_snap.get("operator_shift_logs") or [])
            if isinstance(row, dict) and self._recovery_shift_segment_is_recoverable(row)
        ]
        segment_rows.sort(
            key=lambda row: (
                int(row.get("shift_index") or 0),
                str(row.get("started_at_utc") or row.get("finished_at_utc") or row.get("ended_at_utc") or ""),
            )
        )
        segment_index = 0
        for row in segment_rows:
            segment_key = self._recovery_shift_segment_key_from_row(row, base_snap)
            if segment_key and segment_key in seen_segment_keys:
                continue
            segment_index += 1
            display_snap = dict(row)
            display_snap.setdefault("machine_code", base_snap.get("machine_code"))
            display_snap.setdefault("machine_name", base_snap.get("machine_name"))
            display_snap.setdefault("operator_id", base_snap.get("operator_id"))
            display_snap.setdefault(
                "saved_at_utc",
                row.get("finished_at_utc") or row.get("ended_at_utc") or row.get("started_at_utc"),
            )
            options.append(
                {
                    "kind": "segment",
                    "title": self._recovery_shift_segment_title(row, segment_index),
                    "snap": base_snap,
                    "display_snap": display_snap,
                    "base_snap": base_snap,
                    "segment": row,
                }
            )
            if segment_key:
                seen_segment_keys.add(segment_key)

        return options

    def _recovery_job_codes_from_scan(
        self,
        job_data: Optional[Dict[str, Any]],
        res: Any = None,
        raw_s: str = "",
    ) -> Set[str]:
        keys: Set[str] = set()
        if isinstance(job_data, dict):
            for field in ("job_code", "requested_job_id", "job_name"):
                key = self._normalize_job_code(job_data.get(field))
                if key:
                    keys.add(key)
            payload = job_data.get("job_payload") if isinstance(job_data.get("job_payload"), dict) else {}
            job = self._extract_job_record_from_payload(payload)
            for field in ("id", "ref_no"):
                key = self._normalize_job_code(self._safe_text(job.get(field), ""))
                if key:
                    keys.add(key)
        if res is not None:
            if isinstance(getattr(res, "meta", None), dict):
                key = self._normalize_job_code(res.meta.get("po_number"))
                if key:
                    keys.add(key)
            key = self._normalize_job_code(getattr(res, "value", None))
            if key:
                keys.add(key)
        pack_job = self._extract_job_code_from_pack_qr(str(raw_s or ""))
        if pack_job:
            keys.add(self._normalize_job_code(pack_job))
        raw_key = self._normalize_job_code(raw_s)
        if raw_key:
            keys.add(raw_key)
        return keys

    def _recovery_option_job_codes(self, option: Dict[str, Any]) -> Set[str]:
        keys: Set[str] = set()
        rows: List[Dict[str, Any]] = []
        if str(option.get("kind") or "").strip().lower() == "segment":
            segment = option.get("segment")
            if isinstance(segment, dict):
                rows.append(segment)
        else:
            snap = option.get("snap") if isinstance(option.get("snap"), dict) else option.get("display_snap")
            if isinstance(snap, dict):
                rows.append(snap)
        for row in rows:
            for field in ("job_code", "job_name"):
                key = self._normalize_job_code(row.get(field))
                if key:
                    keys.add(key)
            payload = row.get("job_payload") if isinstance(row.get("job_payload"), dict) else {}
            job = self._extract_job_record_from_payload(payload)
            for field in ("id", "ref_no"):
                key = self._normalize_job_code(self._safe_text(job.get(field), ""))
                if key:
                    keys.add(key)
        return keys

    def _find_recovery_option_for_job(
        self,
        options: List[Dict[str, Any]],
        job_data: Optional[Dict[str, Any]],
        res: Any = None,
        raw_s: str = "",
    ) -> Optional[Dict[str, Any]]:
        scanned_codes = self._recovery_job_codes_from_scan(job_data, res, raw_s)
        if not scanned_codes:
            return None
        segment_match: Optional[Dict[str, Any]] = None
        current_match: Optional[Dict[str, Any]] = None
        for option in options:
            if not (scanned_codes & self._recovery_option_job_codes(option)):
                continue
            if str(option.get("kind") or "").strip().lower() == "segment":
                segment_match = option
            else:
                current_match = option
        return segment_match or current_match

    def _build_recovery_session_options_from_state(self) -> List[Dict[str, Any]]:
        snap = self._state_to_active_snapshot()
        if not isinstance(snap, dict):
            return []
        return self._build_recovery_session_options(snap, None)

    def _find_shift_segment_for_job(self, normalized_job_code: str) -> Optional[Dict[str, Any]]:
        code = str(normalized_job_code or "").strip()
        if not code:
            return None
        for row in reversed(list(self.state.operator_shift_logs or [])):
            if not isinstance(row, dict):
                continue
            if self._normalize_job_code(row.get("job_code")) == code:
                return row
        return None

    def _cancel_session_recovery(self, machine_code: str, server_snap: Optional[Dict[str, Any]]) -> bool:
        code = str(machine_code or "").strip()
        if isinstance(server_snap, dict) and not self._discard_server_recovery(code):
            return False
        self._clear_active_session_snapshot(code)
        return True

    def _restore_shift_segment_from_recovery(
        self,
        base_snap: Dict[str, Any],
        segment: Dict[str, Any],
        machine_name: str,
        note: str,
    ) -> None:
        self._hide_invalid_overlay()
        self._restore_state_from_snapshot(base_snap)
        if not self.state.machine_name:
            self.state.machine_name = _machine_display_name(self.state.machine_code, machine_name)
        s = self.state
        job_code = str(segment.get("job_code") or "").strip()
        if not job_code:
            self.status.setText("Could not recover saved color/mold session: missing job code.")
            return
        operator_id = s.operator_id
        s.job_code = job_code
        s.job_name = str(segment.get("job_name") or job_code).strip()
        s.job_payload = dict(segment.get("job_payload") or {})
        s.job_started_at = str(
            segment.get("started_at_utc")
            or segment.get("finished_at_utc")
            or segment.get("ended_at_utc")
            or datetime.now(timezone.utc).isoformat()
        )
        s.production_session_id = (
            str(segment.get("production_session_id") or "").strip()
            or self._legacy_production_session_id(
                s.machine_code, s.job_code, s.job_started_at, segment.get("client_id")
            )
        )
        self._reset_production_for_color_change_segment()
        s.operator_id = operator_id
        s.pack_count = int(segment.get("pack_count") or 0)
        s.good_total = int(segment.get("good_total") or 0)
        s.butal_total = int(segment.get("butal_total") or 0)
        s.reject_total = int(segment.get("reject_total") or 0)
        s.reject_breakdown = _canonical_reject_breakdown(segment.get("reject_breakdown"))
        s.no_shot_total = int(segment.get("no_shot_total") or 0)
        s.startup_reject_total = int(segment.get("startup_reject_total") or 0)
        s.raw_sacks_count = int(segment.get("raw_sacks_count") or 0)
        s.raw_material_logs = list(segment.get("raw_material_logs") or [])
        s.raw_material_scans = list(segment.get("raw_material_scans") or [])
        s.raw_material_unique_keys = {
            str(item).strip()
            for item in (s.raw_material_scans or [])
            if str(item).strip()
        }
        s.product_pack_history_logs = list(segment.get("product_pack_history_logs") or [])
        s.product_pack_history_keys = {
            self._pack_history_key(row)
            for row in (s.product_pack_history_logs or [])
            if isinstance(row, dict) and self._pack_history_key(row)
        }
        for row in (s.product_pack_history_logs or []):
            if not isinstance(row, dict):
                continue
            pack_key = self._pack_history_key(row)
            if pack_key:
                self._mark_pack_qr_used_permanently(pack_key, row)
        s.butal_scan_logs = list(segment.get("butal_scan_logs") or [])
        s.production_adjustment_logs = list(segment.get("production_adjustment_logs") or [])
        s.cycle_time_current = segment.get("cycle_time_current")
        s.waiting_color_change_job_scan = False
        s.pending_color_change_reason = ""
        self._start_operator_shift_tracking()
        self._reset_operator_shift_baseline_to_full_segment(segment)
        self._ensure_recovered_job_details(job_code)
        self._save_active_session_snapshot()
        self.push_event({"type": "SESSION_RESUME"}, "SESSION RESUMED")
        self.sync_session_snapshot_to_server(note)
        self.status.setText(
            f"Recovered saved session for {self.state.machine_name} / {s.job_name or s.job_code}."
        )
        self._refresh_ui()

    def _complete_session_recovery_option(
        self,
        option: Dict[str, Any],
        machine_name: str,
        note: str = "SESSION SNAPSHOT SYNC (RECOVERY CONFIRMED)",
    ) -> None:
        if str(option.get("kind") or "").strip().lower() == "segment":
            segment = option.get("segment") if isinstance(option.get("segment"), dict) else {}
            base_snap = option.get("base_snap") if isinstance(option.get("base_snap"), dict) else {}
            self._restore_shift_segment_from_recovery(base_snap, segment, machine_name, note)
            return
        snap = option.get("snap") if isinstance(option.get("snap"), dict) else {}
        self._resume_snapshot(snap, machine_name, note)

    def _prompt_session_recovery(
        self,
        machine_code: str,
        machine_name: str,
        server_snap: Optional[Dict[str, Any]],
        local_snap: Optional[Dict[str, Any]],
    ) -> bool:
        options = self._build_recovery_session_options(server_snap, local_snap)
        if not options:
            return False

        server_ok = isinstance(server_snap, dict) and self._snapshot_is_recoverable(server_snap)
        local_ok = isinstance(local_snap, dict) and self._snapshot_is_recoverable(local_snap)
        self._pending_server_recovery = {
            "machine_code": machine_code,
            "machine_name": machine_name,
            "server_snapshot": server_snap if server_ok else None,
            "local_snapshot": local_snap if local_ok else None,
            "options": options,
        }
        self.status.setText(
            f"{len(options)} saved session(s) found. Scan the JOB QR / job order to continue."
        )
        self._show_session_recovery_options_prompt(options)
        return True

    def _job_payload_has_details(self, payload: Any) -> bool:
        if not isinstance(payload, dict):
            return False
        data_obj = payload.get("data") if isinstance(payload.get("data"), dict) else {}
        return isinstance(data_obj.get("job"), dict) or isinstance(payload.get("job"), dict)

    def _ensure_recovered_job_details(self, raw_scan: str = "") -> bool:
        s = self.state
        if not str(s.job_code or s.job_name or "").strip():
            return False
        if self._job_payload_has_details(s.job_payload):
            self._cache_job_payload(s.job_payload, s.job_code, s.job_name, raw_scan)
            return True
        job_identifier = str(s.job_code or s.job_name or "").strip()
        self.status.setText(f"Loading recovered job details from BMS: {job_identifier}")
        fetched_payload = self._fetch_job_payload_from_api(job_identifier)
        if isinstance(fetched_payload, dict):
            api_job = {}
            if isinstance(fetched_payload.get("data"), dict) and isinstance(fetched_payload["data"].get("job"), dict):
                api_job = fetched_payload["data"]["job"]
            elif isinstance(fetched_payload.get("job"), dict):
                api_job = fetched_payload["job"]
            s.job_payload = fetched_payload
            s.job_code = (
                self._safe_text(api_job.get("id"), "")
                or self._safe_text(api_job.get("ref_no"), "")
                or s.job_code
                or job_identifier
            )
            s.job_name = (
                self._safe_text(api_job.get("ref_no"), "")
                or s.job_name
                or job_identifier
            )
            source = "offline cache" if self._last_job_payload_source == "CACHE" else "server"
            self._append_job_api_log(f"RECOVERY job details loaded from {source} for {job_identifier}")
            return True
        self._append_job_api_log(f"RECOVERY job details pending for {job_identifier}")
        self._start_pending_job_api_retry(job_identifier, raw_scan or job_identifier, s.job_name or job_identifier)
        return False

    def _resume_snapshot(self, snap: Dict[str, Any], machine_name: str, note: str) -> None:
        self._hide_invalid_overlay()
        self._restore_state_from_snapshot(snap)
        if not self.state.machine_name:
            self.state.machine_name = _machine_display_name(self.state.machine_code, machine_name)
        self._ensure_recovered_job_details(str(snap.get("job_raw_scan") or snap.get("raw_scan") or snap.get("job_code") or ""))
        self._save_active_session_snapshot()
        self.push_event({"type": "SESSION_RESUME"}, "SESSION RESUMED")
        self.sync_session_snapshot_to_server(note)
        self.status.setText(
            f"Recovered ongoing session for {self.state.machine_name} / {self.state.job_name or self.state.job_code}."
        )
        self._refresh_ui()

    def _discard_server_recovery(self, machine_code: str) -> bool:
        server_url = str((self.client_config or {}).get("server_url", SERVER_URL) or SERVER_URL).strip().rstrip("/")
        try:
            response = requests.post(
                f"{server_url}/api/active-sessions/discard",
                json={"client_id": self._current_client_id(), "machine_code": machine_code},
                timeout=3,
            )
            return response.status_code == 200 and bool(response.json().get("ok"))
        except Exception as e:
            self.status.setText(f"Could not remove saved server session: {e}")
            return False

    def _clear_active_session_snapshot(self, machine_code: Optional[str]):
        code = str(machine_code or "").strip()
        if not code:
            return
        _delete_active_session_json(code)
        self._last_active_session_snapshot_serialized = ""

    def _sync_active_session_snapshots_to_sql(self):
        return

    def _trigger_active_session_sql_sync(self, force: bool = False):
        return

