    def _clear_shift_session_keep_machine(self, *, preserve_carryover: bool = True):
        s = self.state
        active_machine_code = s.machine_code
        active_machine_name = s.machine_name
        last_shift_butal_qty = int(s.last_shift_butal_qty or 0) if preserve_carryover else 0
        last_shift_butal_raw = str(s.last_shift_butal_raw or "") if preserve_carryover else ""
        last_shift_butal_saved_at = s.last_shift_butal_saved_at if preserve_carryover else None
        last_shift_butal_job_code = s.last_shift_butal_job_code if preserve_carryover else None
        last_shift_butal_job_name = s.last_shift_butal_job_name if preserve_carryover else None
        last_shift_butal_by_job = dict(s.last_shift_butal_by_job or {}) if preserve_carryover else {}
        self._clear_full_session()
        s.machine_code = active_machine_code
        s.machine_name = active_machine_name
        s.last_shift_butal_qty = last_shift_butal_qty
        s.last_shift_butal_raw = last_shift_butal_raw
        s.last_shift_butal_saved_at = last_shift_butal_saved_at
        s.last_shift_butal_job_code = last_shift_butal_job_code
        s.last_shift_butal_job_name = last_shift_butal_job_name
        s.last_shift_butal_by_job = last_shift_butal_by_job
        self._save_active_session_snapshot()
        self._broadcast_machine_no_job_running()
        self.status.setText("Finish shift saved. Scan JOB QR.")

    def _broadcast_machine_no_job_running(self):
        s = self.state
        if not s.machine_code:
            return
        snapshot = self._state_to_active_snapshot()
        self.push_event(
            {
                "type": "MACHINE_STATUS",
                "status": "NO_JOB_RUNNING",
                "session_snapshot": snapshot,
            },
            "MACHINE STATUS NO JOB RUNNING",
            silent=True,
        )

    def _extract_production_reason_code(self, raw: str) -> Optional[str]:
        raw_code = str(raw or "").strip()
        if raw_code.isdigit():
            idx = int(raw_code)
            if 1 <= idx <= len(PRODUCTION_DAILY_REPORT_ITEMS):
                return f"{idx:02d}"
            return None
        normalized_reason = re.sub(r"[^A-Z0-9]+", "", raw_code.upper())
        if normalized_reason:
            for code, label in PRODUCTION_DAILY_REPORT_ITEMS:
                if normalized_reason == re.sub(r"[^A-Z0-9]+", "", str(label or "").upper()):
                    return code
        reject_code = raw_code.upper()
        if reject_code not in REJECT_REASON_MAP:
            return None
        m = re.search(r"(\d{2})\s*$", reject_code)
        if not m:
            return None
        try:
            idx = int(m.group(1))
        except Exception:
            return None
        if idx < 1 or idx > len(PRODUCTION_DAILY_REPORT_ITEMS):
            return None
        return f"{idx:02d}"

    def _production_reason_text(self, code: str) -> Optional[str]:
        reason_map = {k: v for k, v in PRODUCTION_DAILY_REPORT_ITEMS}
        return reason_map.get(str(code or "").strip().zfill(2))

    def _pdr_elapsed_seconds(self) -> int:
        s = self.state
        base_seconds = int(s.downtime_last_seconds or s.maintenance_downtime_seconds or 0)
        if s.downtime_started_at:
            return base_seconds + max(0, int(time.time() - s.downtime_started_at))
        return base_seconds

    def _close_pdr_reason_segment(self, ended_by: str) -> Optional[Dict[str, Any]]:
        s = self.state
        code = str(s.downtime_reason_code or "").strip()
        reason = str(s.downtime_reason_text or "").strip()
        if not code:
            return None
        end_seconds = self._pdr_elapsed_seconds()
        start_seconds = s.pdr_current_segment_start_seconds
        if start_seconds is None:
            start_seconds = 0
        row = {
            "segment_index": len(list(s.pdr_reason_segments or [])) + 1,
            "reason_code": code,
            "reason": reason,
            "started_at_seconds": int(start_seconds),
            "ended_at_seconds": int(end_seconds),
            "duration_seconds": max(0, int(end_seconds) - int(start_seconds)),
            "ended_by": ended_by,
            "closed_at_utc": datetime.now(timezone.utc).isoformat(),
        }
        rows = list(s.pdr_reason_segments or [])
        rows.append(row)
        s.pdr_reason_segments = rows
        s.pdr_current_segment_start_seconds = int(end_seconds)
        return row

    def _pdr_total_downtime_seconds(self, *, include_active: bool = False) -> int:
        """Sum completed PDR occurrences, optionally including the current one."""
        s = self.state
        total = sum(
            max(0, int(self._parse_number(row.get("duration_seconds"))))
            for row in (s.pdr_downtime_logs or [])
            if isinstance(row, dict)
        )
        if include_active and (
            s.downtime_active
            or s.downtime_started_at
            or s.waiting_downtime_end_maintenance
            or s.waiting_maintenance_qr
            or s.waiting_cycle_time_input
            or s.waiting_supervisor_qr
        ):
            total += max(0, int(self._pdr_elapsed_seconds()))
        return total

    def _record_completed_pdr_downtime(
        self,
        *,
        confirmed_by: Optional[str] = None,
        confirmed_by_role: Optional[str] = None,
    ) -> Optional[Dict[str, Any]]:
        """Append one completed PDR without replacing earlier shift downtime."""
        s = self.state
        duration = max(0, int(s.downtime_last_seconds or s.maintenance_downtime_seconds or 0))
        segments = [dict(row) for row in (s.pdr_reason_segments or []) if isinstance(row, dict)]
        if duration <= 0 and not segments:
            return None
        finished_at = datetime.now(timezone.utc)
        row = {
            "downtime_index": len(list(s.pdr_downtime_logs or [])) + 1,
            "operator_reason_code": s.pdr_operator_reason_code,
            "operator_reason": s.pdr_operator_reason_text,
            "reason_code": s.downtime_reason_code,
            "reason": s.downtime_reason_text,
            "reason_segments": segments,
            "duration_seconds": duration,
            "waiting_seconds": max(0, int(s.downtime_wait_last_seconds or 0)),
            "started_at_utc": (
                finished_at - timedelta(seconds=duration)
            ).isoformat(),
            "finished_at_utc": finished_at.isoformat(),
            "maintenance": s.maintenance_name,
            "confirmed_by": confirmed_by,
            "confirmed_by_role": confirmed_by_role,
            "cycle_time": s.cycle_time_current,
        }
        rows = list(s.pdr_downtime_logs or [])
        rows.append(row)
        s.pdr_downtime_logs = rows
        return row

    def _operator_code_only(self, operator_text: Optional[str]) -> str:
        if not operator_text:
            return ""
        return str(operator_text).split(" - ", 1)[0].strip()

    def _reset_downtime_resolution_state(self):
        s = self.state
        s.waiting_cycle_time_input = False
        s.waiting_maintenance_qr = False
        s.waiting_supervisor_qr = False
        s.waiting_operator_downtime_confirm = False
        s.downtime_resolution_started_at = None
        s.supervisor_downtime_confirmation_started_at = None
        s.operator_downtime_confirmation_started_at = None
        s.cycle_time_new_input = ""

    def _cancel_pending_pdr_start(self) -> bool:
        s = self.state
        if (
            s.downtime_active
            or s.downtime_started_at
            or s.waiting_downtime_end_maintenance
            or s.maintenance_downtime_seconds is not None
        ):
            return False
        if not (s.waiting_production_report_reason or s.waiting_downtime_start_maintenance or s.waiting_pdr_maintenance_reason):
            return False
        s.waiting_production_report_reason = False
        s.waiting_downtime_start_maintenance = False
        s.waiting_pdr_maintenance_reason = False
        s.pdr_operator_reason_code = None
        s.pdr_operator_reason_text = None
        s.downtime_reason_code = None
        s.downtime_reason_text = None
        s.downtime_wait_started_at = None
        s.downtime_wait_last_seconds = None
        s.downtime_started_at = None
        s.downtime_last_seconds = None
        s.downtime_active = False
        s.maintenance_name = None
        s.pdr_reason_segments = []
        s.pdr_current_segment_start_seconds = None
        s.pdr_followup_reasons_remaining = 0
        self._hide_production_overlay()
        self.status.setText("PDR start cancelled. Continue current job.")
        self._refresh_ui()
        self._save_active_session_snapshot()
        return True

    def _begin_initial_cycle_time_setup(self):
        s = self.state
        s.waiting_initial_cycle_time_input = True
        s.waiting_initial_cycle_qc_confirm = False
        s.waiting_initial_machine_counter_input = False
        s.waiting_shift_end_machine_counter_input = False
        s.cycle_time_new_input = ""
        s.machine_counter_input = ""
        s.cycle_time_confirmed_by = None
        self._hide_production_overlay()
        self.resolveTitle.setText("INITIAL CYCLE TIME SETUP")
        self.resolveHint.setText("Use numpad to input cycle time, then confirm")
        self.resolveOldCycleTitle.setText("JOB STD CYCLE TIME")
        self.resolveNewCycleTitle.setText("CYCLE TIME INPUT")
        std_cycle = "-"
        try:
            payload = s.job_payload or {}
            data = payload.get("data") if isinstance(payload, dict) else {}
            job_details = data.get("job_details") if isinstance(data, dict) else {}
            if isinstance(job_details, dict):
                std_cycle = self._safe_text(job_details.get("std_cycle_time"), "-")
        except Exception:
            std_cycle = "-"
        self.resolveOldCycle.setText(f"Job Std Cycle Time: {std_cycle}")
        self.resolveNewCycle.setText(self._format_resolve_cycle_input_text())
        self._show_resolve_overlay()

    def _repair_initial_setup_state(self):
        """Keep restored/partially completed initial setup on one valid step."""
        s = self.state
        if not (s.machine_code and s.job_code and s.operator_id):
            return
        cycle_valid = self._parse_cycle_seconds(s.cycle_time_current) is not None
        counter_valid = s.machine_counter_shift_start is not None
        initial_flags = bool(
            s.waiting_initial_cycle_time_input
            or s.waiting_initial_cycle_qc_confirm
            or s.waiting_initial_machine_counter_input
        )
        if not initial_flags:
            return
        # The initial QC flag is obsolete; initial cycle entry is confirmed by
        # the confirm QR and then advances directly to machine counter.
        s.waiting_initial_cycle_qc_confirm = False
        if not cycle_valid:
            s.waiting_initial_cycle_time_input = True
            s.waiting_initial_machine_counter_input = False
            return
        s.waiting_initial_cycle_time_input = False
        s.waiting_initial_machine_counter_input = not counter_valid

    def _show_cycle_time_confirm_popup(self, reviewer: Dict[str, str]):
        s = self.state
        s.supervisor_review_open = True
        s.supervisor_review_actor_code = reviewer.get("code")
        s.supervisor_review_actor_name = reviewer.get("name")
        s.supervisor_review_actor_role = reviewer.get("role")
        s.showing_reject_summary = True
        s.reject_summary_last_scanned_at = datetime.now(timezone.utc).isoformat()
        review = self._start_or_update_supervisor_review(reviewer, action="CYCLE_REVIEW_OPEN")
        s.waiting_cycle_time_confirm_popup = True
        s.cycle_time_confirm_phase = 1
        s.cycle_time_confirm_actor_code = reviewer.get("code")
        s.cycle_time_confirm_actor_name = reviewer.get("name")
        s.cycle_time_confirm_actor_role = reviewer.get("role")
        s.cycle_time_new_input = ""
        active_cycle = str(s.cycle_time_temporary or s.cycle_time_current or "").strip() or "-"
        std_cycle = "-"
        try:
            payload = s.job_payload or {}
            data = payload.get("data") if isinstance(payload, dict) else {}
            job_details = data.get("job_details") if isinstance(data, dict) else {}
            if isinstance(job_details, dict):
                std_cycle = self._safe_text(job_details.get("std_cycle_time"), "-")
        except Exception:
            pass
        self.resolveTitle.setText("SUPERVISOR CYCLE TIME REVIEW")
        self.resolveHint.setText(
            f"Active Cycle Time: {active_cycle}\n"
            "Use numpad to update cycle time, then confirm. Scan the same Supervisor badge to save."
        )
        self.resolveOldCycleTitle.setText("STD CYCLE TIME")
        self.resolveNewCycleTitle.setText("NEW CYCLE TIME INPUT")
        self.resolveOldCycle.setText(f"Std Cycle Time: {std_cycle}")
        self.resolveNewCycle.setText(self._format_resolve_cycle_input_text())
        self._show_reject_summary_overlay()
        if review:
            self.push_event({"type": "SUPERVISOR_REVIEW", "review": review}, f"SUPERVISOR REVIEW OPEN {review.get('actor_name') or ''}".strip(), silent=True)

    def _supervisor_review_summary_snapshot(self) -> Dict[str, Any]:
        s = self.state
        return {
            "machine_code": s.machine_code,
            "machine_name": s.machine_name,
            "job_code": s.job_code,
            "job_name": s.job_name,
            "operator_id": s.operator_id,
            "pack_count": int(s.pack_count or 0),
            "good_total": int(s.good_total or 0),
            "butal_total": int(s.butal_total or 0),
            "reject_total": int(s.reject_total or 0),
            "startup_reject_total": int(s.startup_reject_total or 0),
            "no_shot_total": int(s.no_shot_total or 0),
            "reject_breakdown": dict(s.reject_breakdown or {}),
            "cycle_time_current": s.cycle_time_current,
            "cycle_time_temporary": s.cycle_time_temporary,
            "cycle_time_pending_supervisor": bool(s.cycle_time_pending_supervisor),
            "cycle_time_confirmed_by": s.cycle_time_confirmed_by,
            "raw_sacks_count": int(s.raw_sacks_count or 0),
            "raw_material_logs_count": len(s.raw_material_logs or []),
            "pack_history_count": len(s.product_pack_history_logs or []),
            "reject_review_logs_count": len(s.reject_review_logs or []),
            "production_adjustment_logs_count": len(s.production_adjustment_logs or []),
        }

    def _start_or_update_supervisor_review(self, reviewer: Dict[str, Any], action: str = "OPEN") -> Dict[str, Any]:
        s = self.state
        now_utc = datetime.now(timezone.utc).isoformat()
        started_at = str(s.supervisor_review_started_at or "").strip() or now_utc
        s.supervisor_review_started_at = started_at
        review = dict(s.current_supervisor_review or {})
        review.update({
            "review_id": review.get("review_id") or f"SUP-{uuid.uuid4().hex[:10].upper()}",
            "status": "OPEN",
            "action": action,
            "opened_at_utc": started_at,
            "last_updated_at_utc": now_utc,
            "closed_at_utc": None,
            "duration_seconds": None,
            "resolved": False,
            "actor_code": reviewer.get("code") or s.supervisor_review_actor_code,
            "actor_name": reviewer.get("name") or s.supervisor_review_actor_name,
            "actor_role": reviewer.get("role") or s.supervisor_review_actor_role,
            "summary": self._supervisor_review_summary_snapshot(),
        })
        s.current_supervisor_review = review
        return review

    def _close_supervisor_review_snapshot(self, actor_code: str = "", actor_name: str = "", actor_role: str = "", action: str = "CLOSE", resolved: bool = True) -> Optional[Dict[str, Any]]:
        s = self.state
        review = dict(s.current_supervisor_review or {})
        if not review:
            if not (s.supervisor_review_open or s.supervisor_review_started_at):
                return None
            review = self._start_or_update_supervisor_review(
                {
                    "code": actor_code or s.supervisor_review_actor_code or "",
                    "name": actor_name or s.supervisor_review_actor_name or "",
                    "role": actor_role or s.supervisor_review_actor_role or "SUPERVISOR",
                },
                action="RECOVERED_CLOSE",
            )
        now_utc = datetime.now(timezone.utc).isoformat()
        opened_at = str(review.get("opened_at_utc") or s.supervisor_review_started_at or now_utc)
        duration_seconds = 0
        try:
            start_dt = datetime.fromisoformat(opened_at.replace("Z", "+00:00"))
            end_dt = datetime.fromisoformat(now_utc)
            duration_seconds = max(0, int((end_dt - start_dt).total_seconds()))
        except Exception:
            duration_seconds = 0
        review.update({
            "status": "CLOSED",
            "action": action,
            "closed_at_utc": now_utc,
            "last_updated_at_utc": now_utc,
            "duration_seconds": duration_seconds,
            "resolved": bool(resolved),
            "actor_code": actor_code or review.get("actor_code") or s.supervisor_review_actor_code,
            "actor_name": actor_name or review.get("actor_name") or s.supervisor_review_actor_name,
            "actor_role": actor_role or review.get("actor_role") or s.supervisor_review_actor_role or "SUPERVISOR",
            "summary": self._supervisor_review_summary_snapshot(),
        })
        logs = [dict(row) for row in (s.supervisor_review_logs or []) if isinstance(row, dict)]
        review_id = str(review.get("review_id") or "")
        replaced = False
        for idx, row in enumerate(logs):
            if review_id and str(row.get("review_id") or "") == review_id:
                logs[idx] = review
                replaced = True
                break
        if not replaced:
            logs.append(review)
        s.supervisor_review_logs = logs[-100:]
        s.current_supervisor_review = {}
        s.supervisor_review_started_at = None
        return review

    def _hide_cycle_time_confirm_popup(self):
        s = self.state
        s.waiting_cycle_time_confirm_popup = False
        s.cycle_time_confirm_phase = 0
        s.cycle_time_confirm_actor_code = None
        s.cycle_time_confirm_actor_name = None
        s.cycle_time_confirm_actor_role = None
        self._hide_resolve_overlay()

    def _hide_supervisor_review(self):
        s = self.state
        s.supervisor_review_open = False
        s.supervisor_review_actor_code = None
        s.supervisor_review_actor_name = None
        s.supervisor_review_actor_role = None
        s.supervisor_review_started_at = None
        s.current_supervisor_review = {}
        if not s.waiting_cycle_time_confirm_popup:
            s.showing_reject_summary = False
            self._hide_reject_summary_overlay()

    def _finalize_supervisor_cycle_review(self, actor_code: str, actor_name: str, actor_role: str):
        s = self.state
        s.cycle_time_confirmed_by = actor_name
        s.supervisor_name = actor_name
        if str(s.cycle_time_current or "").strip():
            s.cycle_time_supervisor_confirmed = str(s.cycle_time_current).strip()
        s.cycle_time_temporary = None
        s.cycle_time_pending_supervisor = False
        stamp = time.strftime("%Y-%m-%d %H:%M:%S", time.localtime())
        s.reject_review_logs.append(
            {
                "timestamp": stamp,
                "status": "CONFIRMED",
                "actor_role": actor_role,
                "actor_name": actor_name,
                "actor_code": actor_code,
            }
        )
        review = self._close_supervisor_review_snapshot(actor_code, actor_name, actor_role, action="CYCLE_CONFIRMED", resolved=True)
        self._hide_cycle_time_confirm_popup()
        self._hide_supervisor_review()
        self.status.setText(f"Cycle time and reject summary confirmed by {actor_name}")
        self._refresh_ui()
        self._save_active_session_snapshot()
        self.push_event(
            {
                "type": "CYCLE_TIME_CONFIRMED",
                "cycle_time": s.cycle_time_current,
                "confirmed_by_role": actor_role,
                "confirmed_by_name": actor_name,
                "confirmed_by_code": actor_code,
            },
            f"CYCLE TIME CONFIRMED {actor_name}",
        )
        if review:
            self.push_event({"type": "SUPERVISOR_REVIEW", "review": review}, f"SUPERVISOR REVIEW {actor_name}", silent=True)

    def _begin_downtime_resolution(self):
        s = self.state
        self._reset_downtime_resolution_state()
        s.cycle_time_confirmed_by = None
        s.waiting_cycle_time_input = True
        s.downtime_resolution_started_at = time.time()
        s.cycle_time_new_input = ""
        self._set_production_overlay_mode("active")
        self._show_production_overlay()
        self._hide_resolve_overlay()
        self.resolveTitle.setText("DOWNTIME NEW CYCLE TIME")
        self.resolveHint.setText("SCAN NUMKEYS TO INPUT")
        self.resolveOldCycleTitle.setText("NEW CYCLE TIME INPUT")
        self.resolveNewCycleTitle.setText("CONFIRMED BY")
        self.resolveOldCycle.setText(f"New Cycle Time Input: {s.cycle_time_new_input}")
        self.resolveNewCycle.setText("Confirmed by: ")
        self._show_resolve_overlay()

    def _update_cycle_input_display(self):
        self.resolveOldCycle.setText(f"New Cycle Time Input: {self.state.cycle_time_new_input}")
        self.resolveNewCycle.setText(self._format_resolve_cycle_input_text())
        if self.state.waiting_initial_cycle_time_input:
            self.resolveHint.setText("SCAN NUMKEYS, THEN SCAN CONFIRM")
        elif str(self.state.cycle_time_new_input or "").strip():
            self.resolveHint.setText("SCAN QC, MAINTENANCE, OR SUPERVISOR BADGE")
        else:
            self.resolveHint.setText("SCAN NUMKEYS TO INPUT")

    def _refresh_reject_detail_grid(self):
        counts = self._normalized_reject_counts()
        for code, label in REJECT_DETAIL_ITEMS:
            total = int(counts.get(code, 0))
            item = self.reject_detail_labels[code]
            item.setText(str(total))
            is_active = total > 0
            item.setData(Qt.ItemDataRole.UserRole, 1 if is_active else 0)
            item.setData(Qt.ItemDataRole.UserRole + 1, 0)
            if is_active:
                item.setBackground(QColor(254, 226, 226, 90))
                item.setForeground(QColor("#991b1b"))
            else:
                item.setBackground(QColor(0, 0, 0, 0))
                item.setForeground(QColor("#0f172a"))
        self._reject_detail_active_codes = {
            code for code, _label in REJECT_DETAIL_ITEMS if int(counts.get(code, 0)) > 0
        }
        self._sync_reject_detail_header_flash()
        self.rejectDetailTable.viewport().update()

    def _sync_reject_detail_header_flash(self):
        hdr = self.rejectDetailTable.horizontalHeader()
        if isinstance(hdr, RejectDetailHeaderView):
            hdr.set_flash_columns(
                [self._reject_detail_col_by_code.get(code) for code in self._reject_detail_active_codes]
            )
            hdr.set_flash_on(bool(self.enable_flashing_lights and getattr(self, "_reject_detail_flash_on", False)))

    def _tick_reject_detail_flash(self):
        self._reject_detail_flash_on = not self._reject_detail_flash_on
        if self.enable_flashing_lights:
            for item in self.reject_detail_labels.values():
                if int(item.data(Qt.ItemDataRole.UserRole) or 0) == 1:
                    if self._reject_detail_flash_on:
                        item.setBackground(QColor(252, 165, 165, 130))
                    else:
                        item.setBackground(QColor(254, 226, 226, 90))
        self._sync_reject_detail_header_flash()
        self.rejectDetailTable.viewport().update()

    def _on_setting_check_animation_toggled(self, checked: bool):
        self.enable_check_animation = bool(checked)
        self._set_toggle_button_text(self.chkCheckAnimation, "Check animation", self.enable_check_animation)

    def _on_setting_flashing_lights_toggled(self, checked: bool):
        self.enable_flashing_lights = bool(checked)
        self._set_toggle_button_text(self.chkFlashingLights, "Flashing lights", self.enable_flashing_lights)
        if not self.enable_flashing_lights:
            for item in self.reject_detail_labels.values():
                if int(item.data(Qt.ItemDataRole.UserRole) or 0) == 1:
                    item.setBackground(QColor(254, 226, 226, 90))
                else:
                    item.setBackground(QColor(0, 0, 0, 0))
            self.rejectDetailTable.viewport().update()

    def _on_setting_pulse_effects_toggled(self, checked: bool):
        self.enable_pulse_effects = bool(checked)
        self._set_toggle_button_text(self.chkPulseEffects, "Pulse / moving effects", self.enable_pulse_effects)
        if not self.enable_pulse_effects:
            self._overlay_shadow.setColor(Qt.GlobalColor.transparent)
            self._apply_overlay_base_style()
        self._apply_machine_anim_style(str(self.machineAnim.property("mode") or "idle"))

    @staticmethod
    def _normalize_graphics_mode(mode: Any) -> str:
        key = str(mode or "quality").strip().lower().replace(" ", "_")
        if key in ("fast",):
            key = "faster"
        if key in ("faster+quality", "faster_quality", "balanced"):
            key = "faster_quality"
        if key not in ("faster", "faster_quality", "quality"):
            key = "quality"
        return key

    @staticmethod
    def _graphics_mode_label(mode: str) -> str:
        return {
            "faster": "Faster",
            "faster_quality": "Faster + Quality",
            "quality": "Quality",
        }.get(str(mode or "quality"), "Quality")

    def _load_graphics_settings_form(self):
        mode = self._normalize_graphics_mode(self.client_config.get("graphics_mode", "quality"))
        self.graphicsModeToggle.set_mode(mode, emit_signal=False, animate=False)

    def _apply_graphics_mode(self, mode: Any, persist: bool = True):
        mode_key = self._normalize_graphics_mode(mode)
        self.graphics_mode = mode_key
        # Keep scan/void confirmation animation active even in faster modes.
        self.enable_check_animation = True
        self.enable_flashing_lights = mode_key == "quality"
        self.enable_pulse_effects = mode_key == "quality"
        self.enable_heavy_animations = False
        self.enable_background_blur = mode_key == "quality"
        self.enable_gif_animations = True

        self.chkCheckAnimation.blockSignals(True)
        self.chkFlashingLights.blockSignals(True)
        self.chkPulseEffects.blockSignals(True)
        self.chkCheckAnimation.setChecked(self.enable_check_animation)
        self.chkFlashingLights.setChecked(self.enable_flashing_lights)
        self.chkPulseEffects.setChecked(self.enable_pulse_effects)
        self.chkCheckAnimation.blockSignals(False)
        self.chkFlashingLights.blockSignals(False)
        self.chkPulseEffects.blockSignals(False)
        self._set_toggle_button_text(self.chkCheckAnimation, "Check animation", self.enable_check_animation)
        self._set_toggle_button_text(self.chkFlashingLights, "Flashing lights", self.enable_flashing_lights)
        self._set_toggle_button_text(self.chkPulseEffects, "Pulse / moving effects", self.enable_pulse_effects)
        self.chkCheckAnimation.setEnabled(False)
        self.chkFlashingLights.setEnabled(False)
        self.chkPulseEffects.setEnabled(False)

        self.graphicsModeToggle.set_mode(mode_key, emit_signal=False, animate=False)

        if not self.enable_background_blur:
            self._set_background_blur(False)
            self._set_reject_review_blur(False)
        if hasattr(self, "productionFixAnim") and self.productionFixAnim is not None:
            if self.enable_heavy_animations:
                self.productionFixAnim.show()
                self.productionFixAnim.ensure_running()
            else:
                self.productionFixAnim.timer.stop()
                self.productionFixAnim.hide()
        if self.enable_gif_animations and self._invalid_movie is None:
            self._setup_invalid_overlay_media()
        if self._invalid_movie is not None and not self.enable_gif_animations:
            self._invalid_movie.stop()
        self.invalidGifLabel.setVisible(bool(self.enable_gif_animations and self.invalidOverlay.isVisible() and self._invalid_movie is not None))
        if not self.enable_heavy_animations:
            self.invalidGifLabel.setGraphicsEffect(None)
            for attr_name in (
                "productHistoryOverlay",
                "productHistoryOrderNote",
                "resolveOldCard",
                "resolveNewCard",
                "productionWaitingPanel",
                "productionDowntimePanel",
                "productionLiveReason",
                "productionMaintenanceLine",
            ):
                widget = getattr(self, attr_name, None)
                if widget is not None:
                    widget.setGraphicsEffect(None)
            for widget in getattr(self, "productionReasonCards", []) or []:
                try:
                    widget.setGraphicsEffect(None)
                except Exception:
                    pass
        else:
            self._apply_widget_shadow(getattr(self, "resolveOldCard", None), 26, 8, QColor(15, 23, 42, 55))
            self._apply_widget_shadow(getattr(self, "resolveNewCard", None), 26, 8, QColor(15, 23, 42, 55))
            self._apply_widget_shadow(getattr(self, "productionWaitingPanel", None), 12, 2, QColor(0, 0, 0, 62))
            self._apply_widget_shadow(getattr(self, "productionDowntimePanel", None), 12, 2, QColor(0, 0, 0, 62))
            self._apply_widget_shadow(getattr(self, "productionLiveReason", None), 16, 2, QColor(0, 0, 0, 45))
            self._apply_widget_shadow(getattr(self, "productionMaintenanceLine", None), 16, 2, QColor(0, 0, 0, 42))
            if getattr(self, "_product_history_shadow", None) is not None and getattr(self, "productHistoryOverlay", None) is not None:
                self.productHistoryOverlay.setGraphicsEffect(self._product_history_shadow)
            if getattr(self, "_product_history_order_note_shadow", None) is not None and getattr(self, "productHistoryOrderNote", None) is not None:
                self.productHistoryOrderNote.setGraphicsEffect(self._product_history_order_note_shadow)
            for widget in getattr(self, "productionReasonCards", []) or []:
                try:
                    card_shadow = QGraphicsDropShadowEffect(widget)
                    card_shadow.setBlurRadius(16)
                    card_shadow.setOffset(0, 3)
                    card_shadow.setColor(QColor(15, 23, 42, 45))
                    widget.setGraphicsEffect(card_shadow)
                except Exception:
                    pass
        for widget in self.findChildren(CounterCard):
            widget.set_animations_enabled(self.enable_heavy_animations)
        for widget in self.findChildren(CircleProgressBadge):
            widget.set_animations_enabled(self.enable_heavy_animations)
        for widget in self.findChildren(HistoryAnimatedColumn):
            widget.set_animations_enabled(self.enable_heavy_animations)
        self._apply_machine_anim_style(str(self.machineAnim.property("mode") or "idle"))
        self._sync_reject_detail_header_flash()
        self._sync_overlay_pulse_timer()

        if persist:
            self.client_config["graphics_mode"] = mode_key
            _save_client_config(self.client_config)

    def _apply_graphics_settings(self, mode: Optional[str] = None):
        selected = mode if mode is not None else self.graphicsModeToggle.mode()
        self._apply_graphics_mode(selected, persist=True)
        self.status.setText(f"Graphics mode applied: {self._graphics_mode_label(self.graphics_mode)}")

    def _show_settings_section(self, section: str, log_action: bool = True):
        if log_action:
            self._append_app_log("SETTINGS", f"Settings section opened: {section}")
        is_graphics = section == "graphics"
        is_display = section == "display"
        is_api = section == "api"
        is_logs = section == "logs"
        self.settingsBtnGraphics.setChecked(is_graphics)
        self.settingsBtnDisplay.setChecked(is_display)
        self.settingsBtnApi.setChecked(is_api)
        self.settingsBtnLogs.setChecked(is_logs)
        self.settingsGraphicsSection.setVisible(is_graphics)
        self.settingsDisplaySection.setVisible(is_display)
        self.settingsApiSection.setVisible(is_api)
        self.settingsLogsSection.setVisible(is_logs)
        if is_graphics:
            self.settingsContentTitle.setText("Graphics")
        elif is_display:
            self.settingsContentTitle.setText("Display")
        elif is_logs:
            self.settingsContentTitle.setText("App Logs")
            self._refresh_app_logs_table(force=True)
        else:
            self.settingsContentTitle.setText("API Config")

    def _load_api_settings_form(self):
        cfg = self.client_config
        self.apiServerUrlInput.setText(str(cfg.get("server_url", SERVER_URL)))
        self.apiQrgenBaseUrlInput.setText(str(cfg.get("qrgen_base_url", QRGEN_BASE_URL)))
        self.apiClientIdInput.setText(str(cfg.get("client_id", CLIENT_ID)))
        mode = str(cfg.get("scanner_mode", SCANNER_MODE)).strip().lower()
        idx = self.apiScannerModeCombo.findText(mode, Qt.MatchFlag.MatchFixedString)
        self.apiScannerModeCombo.setCurrentIndex(idx if idx >= 0 else 0)
        self.apiScannerPortInput.setText(str(cfg.get("scanner_com_port", SCANNER_COM_PORT)))
        self.apiScannerBaudInput.setText(str(cfg.get("scanner_baudrate", SCANNER_BAUDRATE)))
        self.apiScannerTimeoutInput.setText(str(cfg.get("scanner_timeout", SCANNER_TIMEOUT)))
        self.apiPackScanIntervalInput.setText(str(cfg.get("pack_scan_interval_seconds", PACK_SCAN_INTERVAL_SECONDS)))
        self.apiPartAvailabilityThresholdInput.setText(str(cfg.get("part_availability_warning_threshold_percent", 10.0)))
        self.apiProductPartRestrictionToggle.setChecked(
            bool(cfg.get("product_part_restriction_enabled", True))
        )
        jcfg = getattr(self, "job_api_config", {}) or {}
        self.apiJobApiBaseUrlInput.setText(str(jcfg.get("base_url", "")))
        self.apiJobApiUserInput.setText(str(jcfg.get("user") or jcfg.get("username") or ""))
        self.apiJobApiTokenInput.setText(str(jcfg.get("bearer_token", "")))
        self.apiJobApiPasswordInput.setText(str(jcfg.get("password", "")))
    def _apply_api_settings(self):
        server_url = self.apiServerUrlInput.text().strip().rstrip("/")
        qrgen_base_url = self.apiQrgenBaseUrlInput.text().strip().rstrip("/")
        client_id = self.apiClientIdInput.text().strip() or socket.gethostname()
        client_id = re.sub(r"\s+", "-", client_id)
        scanner_mode = self.apiScannerModeCombo.currentText().strip().lower()
        scanner_port = self.apiScannerPortInput.text().strip()
        job_api_base_url = self.apiJobApiBaseUrlInput.text().strip().rstrip("/")
        job_api_user = self.apiJobApiUserInput.text().strip()
        job_api_token = self.apiJobApiTokenInput.text()
        job_api_password = self.apiJobApiPasswordInput.text()
        if not server_url:
            self.status.setText("API config failed: Server URL is required.")
            return
        if not qrgen_base_url or not re.match(r"^https?://", qrgen_base_url, flags=re.IGNORECASE):
            self.status.setText("API config failed: Barcode Printer API must be a valid http:// or https:// URL.")
            self._show_invalid_overlay("Enter the Barcode Printer API base URL, for example http://192.168.10.50:5000.")
            return
        if scanner_mode not in ("auto", "keyboard", "serial"):
            self.status.setText("API config failed: invalid scanner mode.")
            return
        try:
            scanner_baudrate = int(self.apiScannerBaudInput.text().strip())
            if scanner_baudrate <= 0:
                raise ValueError()
        except Exception:
            self.status.setText("API config failed: Scanner baudrate must be a positive integer.")
            return
        try:
            scanner_timeout = float(self.apiScannerTimeoutInput.text().strip())
            if scanner_timeout < 0:
                raise ValueError()
        except Exception:
            self.status.setText("API config failed: Scanner timeout must be 0 or greater.")
            return
        try:
            pack_scan_interval = float(self.apiPackScanIntervalInput.text().strip())
            if pack_scan_interval < 0:
                raise ValueError()
        except Exception:
            self.status.setText("API config failed: PACK scan lock interval must be 0 or greater.")
            return
        try:
            part_warning_threshold = float(self.apiPartAvailabilityThresholdInput.text().strip())
            if part_warning_threshold < 0 or part_warning_threshold > 100:
                raise ValueError()
        except Exception:
            self.status.setText("API config failed: Product Part threshold must be from 0 to 100 percent.")
            return

        old_client_id = self._current_client_id()
        candidate_client_config = dict(self.client_config)
        candidate_client_config.update({
            "server_url": server_url,
            "qrgen_base_url": qrgen_base_url,
            "client_id": client_id,
            "scanner_mode": scanner_mode,
            "scanner_com_port": scanner_port or SCANNER_COM_PORT,
            "scanner_baudrate": scanner_baudrate,
            "scanner_timeout": scanner_timeout,
            "pack_scan_interval_seconds": pack_scan_interval,
            "part_availability_warning_threshold_percent": part_warning_threshold,
            "product_part_restriction_enabled": bool(
                self.apiProductPartRestrictionToggle.isChecked()
            ),
        })
        candidate_job_api_config = dict(self.job_api_config)
        candidate_job_api_config.update({
            "base_url": job_api_base_url,
            "user": job_api_user,
            "username": job_api_user,
            "password": job_api_password,
            "bearer_token": job_api_token,
        })
        if not _save_client_config(candidate_client_config):
            self.status.setText("Configuration was not applied: client settings could not be saved.")
            self._show_invalid_overlay("Settings save failed. Check the Database folder permissions or free disk space.")
            return
        if not _save_job_api_config(candidate_job_api_config):
            _save_client_config(dict(self.client_config))
            self.status.setText("Configuration was not applied: Job API settings could not be saved.")
            self._show_invalid_overlay("Job API settings save failed. Check the Database folder permissions or free disk space.")
            return
        self.client_config = candidate_client_config
        self.job_api_config = candidate_job_api_config
        # Reload the form from the committed runtime values so the operator can
        # immediately see exactly what was saved.
        self._load_api_settings_form()
        self._sync_product_parts_missing_error_after_refresh()
        self._restart_scanner_input()
        self._trigger_identity_cache_sync(force=True)
        restriction_status = (
            "ON (insufficient balance blocked)"
            if self.apiProductPartRestrictionToggle.isChecked()
            else "OFF"
        )
        identity_note = f" Client ID: {client_id}."
        if old_client_id != client_id and self.state.machine_code:
            self.sync_session_snapshot_to_server("SESSION SNAPSHOT SYNC (CLIENT ID CONFIG CHANGED)")
            identity_note = f" Client ID changed: {old_client_id} -> {client_id}; server sync queued."
        self._append_app_log("SETTINGS", f"API configuration saved; client_id={client_id}; qrgen={qrgen_base_url}")
        self.status.setText(
            f"API/Scanner configuration saved and applied.{identity_note} Barcode Printer API: {qrgen_base_url}. Product Part Restriction: {restriction_status}."
        )

    def _test_job_api_settings(self):
        server_url = self.apiServerUrlInput.text().strip().rstrip("/") or str(self.client_config.get("server_url", SERVER_URL)).strip().rstrip("/")
        if not server_url:
            self.status.setText("Job API test failed: Server URL is required.")
            return
        job_id, ok = QInputDialog.getText(self, "Test Job API", "Enter Job ID to test (GET /v1/jobs/{id}):")
        if not ok:
            self.status.setText("Job API test cancelled.")
            return
        job_id = str(job_id).strip()
        if not job_id:
            self.status.setText("Job API test failed: Job ID is required.")
            return
        try:
            resp = self._request_with_ui_events(
                requests.post,
                f"{server_url}/api/jobs/lookup",
                headers={"Content-Type": "application/json", "Accept": "application/json"},
                json={"job_identifier": job_id},
                timeout=5,
            )
            self._append_job_api_log(f"TEST SERVER JOB LOOKUP {job_id} -> HTTP {resp.status_code}")
            print(f"[JobAPI] TEST SERVER JOB LOOKUP {job_id} -> HTTP {resp.status_code}")
            if resp.status_code != 200:
                self.status.setText(
                    f"Server job lookup failed HTTP {resp.status_code}: {self._http_error_snippet(resp) or 'No response body'}"
                )
                self._append_job_api_log(f"TEST FAIL: {self._http_error_snippet(resp) or 'No response body'}")
                return
            out = resp.json()
            payload = out.get("payload") if isinstance(out, dict) else {}
            if not isinstance(payload, dict):
                self.status.setText("Server job lookup failed: no payload returned.")
                return
            job = {}
            if isinstance(payload.get("data"), dict):
                job = payload["data"].get("job") or {}
            elif isinstance(payload.get("job"), dict):
                job = payload.get("job") or {}
            ref = str((job or {}).get("ref_no", "")).strip()
            jid = str((job or {}).get("id", "")).strip() or job_id
            self.status.setText(f"Server job lookup OK: {jid}{' / ' + ref if ref else ''}")
            self._append_job_api_log(f"TEST SERVER OK: {jid}{' / ' + ref if ref else ''}")
        except Exception as e:
            self.status.setText(f"Server job lookup test failed: {e}")
            self._append_job_api_log(f"TEST ERROR: {e}")
            print(f"[JobAPI] TEST ERROR: {e}")

    def _refresh_all_running_job_details(self):
        """Refresh API payloads without resetting the active production session."""
        s = self.state
        if not s.job_code:
            self.status.setText("No running jobs to refresh.")
            return
        refreshed = 0
        failed: List[str] = []
        self._show_bms_loading("Refreshing all running jobs from BMS...")
        try:
            main_payload = self._fetch_job_payload_from_api(str(s.job_code or ""))
            if isinstance(main_payload, dict):
                main_job = self._extract_job_record_from_payload(main_payload)
                s.job_payload = main_payload
                s.job_name = (
                    self._safe_text(main_job.get("ref_no"), "")
                    or s.job_name
                    or s.job_code
                )
                refreshed += 1
            else:
                failed.append(str(s.job_name or s.job_code))

            for row in (s.linkage_jobs or []):
                if not isinstance(row, dict):
                    continue
                code = str(row.get("job_code") or "").strip()
                payload = self._fetch_job_payload_from_api(code) if code else None
                if not isinstance(payload, dict):
                    failed.append(str(row.get("job_name") or code or "linked job"))
                    continue
                job = self._extract_job_record_from_payload(payload)
                row["job_payload"] = payload
                row["job_name"] = (
                    self._safe_text(job.get("ref_no"), "")
                    or row.get("job_name")
                    or code
                )
                refreshed += 1
        finally:
            self._hide_bms_loading()

        primary_code = self._normalize_job_code(s.linkage_job_code)
        primary = next(
            (
                row for row in (s.linkage_jobs or [])
                if isinstance(row, dict)
                and self._normalize_job_code(row.get("job_code")) == primary_code
            ),
            None,
        )
        if isinstance(primary, dict):
            s.linkage_job_name = primary.get("job_name")
            s.linkage_job_payload = primary.get("job_payload") or {}
        self._job_parts_table_refresh_key = ""
        self._refresh_ui(force=True)
        self._save_active_session_snapshot()
        self.sync_session_snapshot_to_server("SESSION SNAPSHOT SYNC (REFRESH ALL JOB DETAILS)")
        if failed:
            self.status.setText(
                f"Refreshed {refreshed} running job(s). Failed: {', '.join(failed[:3])}."
            )
        else:
            self.status.setText(f"Refreshed all {refreshed} running job(s) from BMS.")

    def _running_work_order_rows(self) -> List[Dict[str, Any]]:
        rows: List[Dict[str, Any]] = []
        if self.state.job_code:
            rows.append({
                "slot": "MAIN",
                "index": None,
                "job_code": self.state.job_code,
                "job_name": self.state.job_name,
            })
        for index, row in enumerate(self.state.linkage_jobs or []):
            if not isinstance(row, dict):
                continue
            rows.append({
                "slot": "LINKED",
                "index": index,
                "job_code": row.get("job_code"),
                "job_name": row.get("job_name"),
            })
        return rows

    def _show_change_work_order_selection(self):
        rows = self._running_work_order_rows()
        lines = [
            f"{idx + 1}. {row.get('job_name') or row.get('job_code') or '-'} "
            f"[{row.get('slot')}]"
            for idx, row in enumerate(rows)
        ]
        self._show_info_overlay(
            "CHANGE WORK ORDER",
            "Select the work order to replace by scanning its JOB QR.\n\n"
            + ("\n".join(lines) if lines else "No running work orders."),
            hide_ms=0,
        )

    def _show_remove_job_linkage_selection(self):
        linked_rows = [row for row in (self.state.linkage_jobs or []) if isinstance(row, dict)]
        lines = [
            f"{idx + 1}. {row.get('job_name') or row.get('job_code') or '-'}"
            for idx, row in enumerate(linked_rows)
        ]
        self._show_info_overlay(
            "REMOVE JOB LINKAGE",
            "Scan the linked JOB QR that you want to remove.\n\n"
            + ("\n".join(lines) if lines else "No linked jobs are currently running."),
            hide_ms=0,
        )

    def _handle_remove_job_linkage_scan(self, res: Any, raw_s: str) -> bool:
        if not bool(getattr(self, "_remove_job_linkage_mode", False)):
            return False
        candidates = {self._normalize_job_code(res.value)}
        if isinstance(res.meta, dict):
            candidates.add(self._normalize_job_code(res.meta.get("po_number")))
        candidates.add(self._normalize_job_code(raw_s))
        candidates.discard("")
        index = next(
            (
                i for i, row in enumerate(self.state.linkage_jobs or [])
                if isinstance(row, dict)
                and (
                    self._normalize_job_code(row.get("job_code")) in candidates
                    or self._normalize_job_code(row.get("job_name")) in candidates
                )
            ),
            None,
        )
        if index is None:
            self.status.setText("That JOB is not linked to the current main job.")
            self._show_invalid_overlay("Scan one of the linked JOB QRs shown in the list.")
            return True

        removed = self.state.linkage_jobs.pop(index)
        removed_code = str(removed.get("job_code") or "").strip()
        removed_name = str(removed.get("job_name") or removed_code or "linked job").strip()
        remaining = [row for row in (self.state.linkage_jobs or []) if isinstance(row, dict)]
        self.state.linkage_enabled = bool(remaining)
        if self._normalize_job_code(self.state.linkage_job_code) == self._normalize_job_code(removed_code):
            primary = remaining[-1] if remaining else {}
            self.state.linkage_job_code = primary.get("job_code")
            self.state.linkage_job_name = primary.get("job_name")
            self.state.linkage_job_payload = primary.get("job_payload") or {}
        if self._normalize_job_code(self.state.prepack_active_job_code) == self._normalize_job_code(removed_code):
            self.state.prepack_active_job_code = (remaining[0].get("job_code") if remaining else None)
        self._offline_pack_main_qty_overrides.pop(self._normalize_job_code(removed_code), None)
        self._remove_job_linkage_mode = False
        self._hide_invalid_overlay()
        self.status.setText(f"Job linkage removed: {removed_name}. Main job and production history were preserved.")
        self._job_parts_table_refresh_key = ""
        self._refresh_ui(force=True)
        self._save_active_session_snapshot()
        self.sync_session_snapshot_to_server("SESSION SNAPSHOT SYNC (JOB LINKAGE REMOVED)")
        self.push_event(
            {
                "type": "JOB_LINKAGE_REMOVED",
                "removed_job_code": removed_code,
                "removed_job_name": removed_name,
            },
            f"JOB LINKAGE REMOVED {removed_name}",
        )
        return True

    def _handle_change_work_order_job_scan(self, res: Any, raw_s: str) -> bool:
        phase = str(getattr(self, "_change_work_order_phase", "") or "").upper()
        if not phase:
            return False
        s = self.state
        if phase == "SELECT":
            scanned_identifier = ""
            if isinstance(res.meta, dict):
                scanned_identifier = self._safe_text(res.meta.get("po_number"), "")
            candidate_keys = {
                self._normalize_job_code(scanned_identifier),
                self._normalize_job_code(res.value),
            }
            candidate_keys.discard("")
            target = next(
                (
                    row for row in self._running_work_order_rows()
                    if self._normalize_job_code(row.get("job_code")) in candidate_keys
                    or self._normalize_job_code(row.get("job_name")) in candidate_keys
                ),
                None,
            )
            if target is None:
                self.status.setText("That JOB is not currently running on this machine.")
                self._show_invalid_overlay("Scan one of the listed running JOB QRs.")
                return True
            self._change_work_order_target = dict(target)
            self._change_work_order_phase = "REPLACE"
            label = str(target.get("job_name") or target.get("job_code") or "selected job")
            self.status.setText(f"Selected {label}. Scan the NEW JOB QR that will replace it.")
            self._show_info_overlay(
                "SCAN REPLACEMENT JOB",
                f"Selected: {label} [{target.get('slot')}]\n\n"
                "Now scan the NEW JOB QR. Production history and counters will be preserved.",
                hide_ms=0,
            )
            return True

        target = self._change_work_order_target
        if not isinstance(target, dict):
            self._change_work_order_phase = ""
            return False
        job_data = self._resolve_scanned_job_data(res, raw_s, "Getting replacement job data from BMS...")
        if not isinstance(job_data, dict) or not isinstance(job_data.get("job_payload"), dict) or not job_data.get("job_payload"):
            self.status.setText("Replacement failed: unable to get the new job details from BMS.")
            self._show_invalid_overlay("New work order was not changed. Scan a valid JOB QR.")
            return True
        new_code = str(job_data.get("job_code") or "").strip()
        old_code = str(target.get("job_code") or "").strip()
        other_codes = {
            self._normalize_job_code(row.get("job_code"))
            for row in self._running_work_order_rows()
            if self._normalize_job_code(row.get("job_code")) != self._normalize_job_code(old_code)
        }
        if self._normalize_job_code(new_code) in other_codes:
            self.status.setText("Replacement blocked: that work order is already running on this machine.")
            self._show_invalid_overlay("Choose a work order that is not already linked.")
            return True

        new_name = str(job_data.get("job_name") or new_code).strip()
        new_payload = job_data.get("job_payload") or {}
        if target.get("slot") == "MAIN":
            s.job_code = new_code
            s.job_name = new_name
            s.job_payload = new_payload
        else:
            index = int(target.get("index"))
            if index < 0 or index >= len(s.linkage_jobs or []):
                self.status.setText("Replacement cancelled: linked-job slot no longer exists.")
                self._change_work_order_phase = ""
                self._change_work_order_target = None
                return True
            linked = s.linkage_jobs[index]
            linked.update({
                "job_code": new_code,
                "job_name": new_name,
                "job_payload": new_payload,
            })
            if self._normalize_job_code(s.linkage_job_code) == self._normalize_job_code(old_code):
                s.linkage_job_code = new_code
                s.linkage_job_name = new_name
                s.linkage_job_payload = new_payload
        if isinstance(s.butal_by_job, dict) and old_code in s.butal_by_job:
            s.butal_by_job[new_code] = s.butal_by_job.pop(old_code)
        self._change_work_order_phase = ""
        self._change_work_order_target = None
        self._job_parts_table_refresh_key = ""
        self._hide_invalid_overlay()
        self.status.setText(f"Work order changed: {old_code} -> {new_name}. Job details refreshed.")
        self._refresh_ui(force=True)
        self._save_active_session_snapshot()
        self.sync_session_snapshot_to_server("SESSION SNAPSHOT SYNC (CHANGE WORK ORDER)")
        self.push_event(
            {"type": "CHANGE_WORK_ORDER", "old_job_code": old_code, "new_job_code": new_code},
            f"CHANGE WORK ORDER {old_code} -> {new_code}",
        )
        return True

    def _restart_scanner_input(self):
        self._serial_stop.set()
        if self._serial_thread and self._serial_thread.is_alive():
            self._serial_thread.join(timeout=1.0)
        self._serial_thread = None
        if hasattr(self, "filter"):
            try:
                self.removeEventFilter(self.filter)
            except Exception:
                pass
            self.filter = None
        self._serial_stop = threading.Event()
        self._setup_scanner_input()

    def _apply_display_settings(self):
        os_name = self.displayOsCombo.currentText().strip()
        size_name = self.displaySizeCombo.currentText().strip()
        self.setWindowState(Qt.WindowState.WindowNoState)
        if size_name.lower() == "fullscreen":
            self.showFullScreen()
            self.status.setText(f"Display applied: {os_name} / Fullscreen")
            return

        m = re.match(r"^\s*(\d+)\s*x\s*(\d+)\s*$", size_name)
        if m:
            w = max(800, int(m.group(1)))
            h = max(480, int(m.group(2)))
            self.showNormal()
            self.resize(w, h)
            self.status.setText(f"Display applied: {os_name} / {w}x{h}")
            return
        self.status.setText("Display apply failed: invalid size preset.")

    def _set_toggle_button_text(self, btn: QPushButton, label: str, enabled: bool):
        btn.setText(f"{label}: {'ON' if enabled else 'OFF'}")

    def _should_keep_background_blur(self) -> bool:
        return (
            self.productionOverlay.isVisible()
            or self.resolveOverlay.isVisible()
            or self.rawMatsOverlay.isVisible()
            or self.rejectSummaryOverlay.isVisible()
            or self.productHistoryOverlay.isVisible()
            or self.rejectReviewOverlay.isVisible()
            or self.finishOverlay.isVisible()
            or self.settingsOverlay.isVisible()
        )

    def _safe_text(self, v: Any, fallback: str = "-") -> str:
        if v is None:
            return fallback
        s = str(v).strip()
        return s if s else fallback

    def _parse_number(self, value: Any) -> float:
        if value is None:
            return 0.0
        raw = str(value).strip().replace(",", "")
        if not raw:
            return 0.0
        try:
            return float(raw)
        except Exception:
            m = re.search(r"-?\d+(?:\.\d+)?", raw)
            if not m:
                return 0.0
            try:
                return float(m.group(0))
            except Exception:
                return 0.0

    def _clear_external_average_weight(self):
        s = self.state
        s.external_average_weight_grams = None
        s.external_average_weight_unit = None
        s.external_average_weight_received_at = None
        s.external_average_weight_sent_at = None
        s.external_average_weight_source = None
        s.external_average_weight_sender = None
        s.external_average_weight_needs_refresh = False

    def _job_part_rows(self, payload: Optional[Dict[str, Any]] = None) -> List[Dict[str, Any]]:
        def _rows_from_payload(source: Any) -> List[Dict[str, Any]]:
            base_payload = source if isinstance(source, dict) else {}
            data_obj = base_payload.get("data") if isinstance(base_payload.get("data"), dict) else {}
            job = data_obj.get("job") if isinstance(data_obj.get("job"), dict) else {}
            if not job and isinstance(base_payload.get("job"), dict):
                job = base_payload.get("job") or {}
            job_details = {}
            if isinstance(job.get("job_details"), dict):
                job_details = job.get("job_details") or {}
            elif isinstance(base_payload.get("job_details"), dict):
                job_details = base_payload.get("job_details") or {}
            elif isinstance(data_obj.get("job_details"), dict):
                job_details = data_obj.get("job_details") or {}
            if isinstance(data_obj.get("parts"), list):
                return [r for r in data_obj.get("parts") or [] if isinstance(r, dict)]
            if isinstance(job_details.get("parts"), list):
                return [r for r in job_details.get("parts") or [] if isinstance(r, dict)]
            if isinstance(job_details.get("part_ids"), list):
                return [r for r in job_details.get("part_ids") or [] if isinstance(r, dict)]
            if isinstance(job_details.get("part_ids"), dict):
                return [job_details.get("part_ids") or {}]
            if isinstance(data_obj.get("part_ids"), list):
                return [r for r in data_obj.get("part_ids") or [] if isinstance(r, dict)]
            if isinstance(base_payload.get("part_ids"), list):
                return [r for r in base_payload.get("part_ids") or [] if isinstance(r, dict)]
            return []

        # An explicit payload lookup must stay isolated (used for linked-job
        # identity and finished-record calculations).
        if isinstance(payload, dict):
            return _rows_from_payload(payload)

        main_source_label = str(self.state.job_name or self.state.job_code or "MAIN JOB").strip()
        sources: List[tuple[str, str, Dict[str, Any]]] = [
            (main_source_label, self._normalize_job_code(self.state.job_code), self.state.job_payload or {}),
        ]
        linked_rows = [row for row in (self.state.linkage_jobs or []) if isinstance(row, dict)]
        if self.state.linkage_enabled and linked_rows:
            # In the normal multicolor linkage flow, the first linked P job is
            # the packing work order.  Any other linked jobs are checking-only,
            # so their product parts must not appear in the production parts
            # table or participate in its consumption calculations.
            packing_row = self._normal_linkage_packing_row()
            packing_code = self._normalize_job_code(
                packing_row.get("job_code") if isinstance(packing_row, dict) else None
            )
            for linked in linked_rows:
                linked_code = self._normalize_job_code(linked.get("job_code"))
                if packing_code and linked_code != packing_code:
                    continue
                linked_payload = linked.get("job_payload") if isinstance(linked.get("job_payload"), dict) else {}
                sources.append((
                    str(linked.get("job_name") or linked.get("job_code") or "LINKED JOB"),
                    linked_code,
                    linked_payload,
                ))

        combined: List[Dict[str, Any]] = []
        seen: Dict[str, int] = {}
        for source_label, source_job_code, source_payload in sources:
            for raw_part in _rows_from_payload(source_payload):
                part = dict(raw_part)
                part["required_from_job"] = source_label
                part["required_from_job_code"] = source_job_code or None
                product_id = self._normalize_material_match_key(
                    part.get("part_product_id") or part.get("product_id")
                )
                sku = self._normalize_material_match_key(
                    part.get("sku") or part.get("part_sku") or part.get("product_sku")
                )
                material_key = f"ID:{product_id}" if product_id else (f"SKU:{sku}" if sku else "")
                key = f"{source_job_code}|{material_key}" if material_key else ""
                if key and key in seen:
                    existing = combined[seen[key]]
                    existing_request = self._parse_number(existing.get("request_part_qty"))
                    added_request = self._parse_number(part.get("request_part_qty"))
                    if added_request > 0:
                        existing["request_part_qty"] = existing_request + added_request
                    continue
                if key:
                    seen[key] = len(combined)
                combined.append(part)
        # When BMS details are unavailable, product parts learned through the
        # offline num_0 classification become the job's consumable part list.
        # Nothing is shown until at least one PRODUCT PART QR has been scanned.
        offline_parts: Dict[str, Dict[str, Any]] = {}
        for log_row in (self.state.raw_material_logs or []):
            if not isinstance(log_row, dict):
                continue
            if str(log_row.get("source") or "").strip().upper() != "OFFLINE_CONFIRMED_PRODUCT_PART":
                continue
            product_id = str(
                log_row.get("material_product_id")
                or log_row.get("product_id")
                or ""
            ).strip()
            sku = str(
                log_row.get("material_sku")
                or log_row.get("job_part_sku")
                or ""
            ).strip()
            material_key = (
                f"ID:{self._normalize_material_match_key(product_id)}"
                if product_id
                else f"SKU:{self._normalize_material_match_key(sku)}"
            )
            if material_key in ("ID:", "SKU:"):
                continue
            existing_key = (
                f"{self._normalize_job_code(self.state.job_code)}|{material_key}"
            )
            if existing_key in seen:
                continue
            row = offline_parts.setdefault(
                material_key,
                {
                    "part_product_id": product_id or None,
                    "product_id": product_id or None,
                    "sku": sku or (f"PRODUCT-{product_id}" if product_id else "OFFLINE-PART"),
                    "name": str(
                        log_row.get("material_name")
                        or log_row.get("material")
                        or sku
                        or f"Product Part {product_id}"
                    ).strip(),
                    "unit": "pc",
                    "part_qty_per_unit": 1,
                    "request_part_qty": 0,
                    "required_from_job": main_source_label,
                    "required_from_job_code": self._normalize_job_code(self.state.job_code) or None,
                    "offline_confirmed_part": True,
                },
            )
            row["request_part_qty"] = (
                self._parse_number(row.get("request_part_qty"))
                + max(0.0, self._parse_number(log_row.get("qty")))
            )
        combined.extend(offline_parts.values())
        return combined

    def _resolve_part_qty_per_unit(self, part: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
        s = self.state
        unit_kind = self._part_unit_kind(part)
        api_part_qty = 0.0
        if isinstance(part, dict):
            for key in (
                "part_qty_per_unit",
                "qty_per_unit",
                "quantity_per_unit",
                "part_quantity_per_unit",
                "component_qty_per_unit",
            ):
                api_part_qty = self._parse_number(part.get(key))
                if api_part_qty > 0:
                    break
        if isinstance(part, dict) and unit_kind == "pc":
            if api_part_qty > 0:
                return {
                    "value": api_part_qty,
                    "source": "job_api",
                    "unit": "pc",
                    "label": f"Job API ({api_part_qty:.4f} pc)",
                }
        ext_weight = s.external_average_weight_grams
        ext_unit = str(s.external_average_weight_unit or "g").strip() or "g"
        if ext_weight is not None and ext_weight > 0:
            ext_kg = float(ext_weight) / 1000.0
            return {
                "value": ext_kg,
                "source": "app",
                "unit": "kg",
                "label": f"App ({ext_kg:.4f} kg)",
            }
        if api_part_qty > 0:
            return {
                "value": api_part_qty,
                "source": "job_api_default_weight",
                "unit": "kg",
                "label": f"Job API default weight ({api_part_qty:.4f} kg)",
            }
        if unit_kind == "kg":
            return {
                "value": 0.0,
                "source": "missing",
                "unit": "kg",
                "label": "Waiting for part qty/unit",
            }
        return {
            "value": 0.0,
            "source": "missing",
            "unit": "kg",
            "label": "No part qty/unit",
        }

    def _format_part_qty_per_unit_display(self, qty_value: float, unit_kind: str = "") -> str:
        qty = float(qty_value or 0.0)
        if qty <= 0:
            return "0.0000"
        suffix = "kg" if str(unit_kind or "").lower() == "kg" else "pc"
        return f"{qty:.4f} {suffix}"

    def _raw_consumption_unit_count(self, source: Dict[str, Any]) -> float:
        """Return units that may consume product parts.

        Reject, startup-reject, and no-shot scans are production records only.
        They must remain in their reject histories/totals, but they do not
        consume scanned product-part availability.
        """
        if not isinstance(source, dict):
            return 0.0
        return max(
            0.0,
            self._parse_number(source.get("good_total"))
            + self._parse_number(source.get("butal_total")),
        )

    def _normalize_material_match_key(self, value: Any) -> str:
        text = str(value or "").strip().upper()
        if not text:
            return ""
        return re.sub(r"[^A-Z0-9]+", "", text)

    def _part_material_match_keys(self, part: Optional[Dict[str, Any]]) -> Set[str]:
        keys: Set[str] = set()
        if not isinstance(part, dict):
            return keys
        for raw in (
            part.get("sku"),
            part.get("part_sku"),
            part.get("part_product_id"),
            part.get("product_id"),
            part.get("material_code"),
            part.get("name"),
        ):
            norm = self._normalize_material_match_key(raw)
            if norm:
                keys.add(norm)
        return keys

    def _part_material_name_keys(self, part: Optional[Dict[str, Any]]) -> Set[str]:
        keys: Set[str] = set()
        if not isinstance(part, dict):
            return keys
        for raw in (
            part.get("name"),
            part.get("part_name"),
            part.get("material_name"),
            part.get("product_name"),
            part.get("description"),
        ):
            norm = self._normalize_material_match_key(raw)
            if norm:
                keys.add(norm)
        return keys

    def _raw_material_match_keys(self, row: Optional[Dict[str, Any]]) -> Set[str]:
        keys: Set[str] = set()
        if not isinstance(row, dict):
            return keys
        for raw in (
            row.get("material_sku"),
            row.get("sku"),
            row.get("material_product_id"),
            row.get("product_id"),
            row.get("material_code"),
            row.get("material_name"),
            row.get("material"),
        ):
            norm = self._normalize_material_match_key(raw)
            if norm:
                keys.add(norm)
        return keys

    def _raw_material_name_keys(self, row: Optional[Dict[str, Any]]) -> Set[str]:
        keys: Set[str] = set()
        if not isinstance(row, dict):
            return keys
        for raw in (
            row.get("material_name"),
            row.get("material"),
            row.get("product_name"),
            row.get("name"),
        ):
            norm = self._normalize_material_match_key(raw)
            if norm:
                keys.add(norm)
        product_id = str(
            row.get("material_product_id")
            or row.get("product_id")
            or row.get("material_code")
            or ""
        ).strip()
        if product_id:
            catalog_name = self._lookup_product_name(product_id)
            norm = self._normalize_material_match_key(catalog_name)
            if norm:
                keys.add(norm)
        return keys

    def _part_unit_kind(self, part: Optional[Dict[str, Any]]) -> str:
        if not isinstance(part, dict):
            return "pc"
        unit_text = " ".join(
            str(part.get(key) or "")
            for key in (
                "unit",
                "uom",
                "part_unit",
                "qty_unit",
                "quantity_unit",
                "request_part_unit",
                "request_unit",
            )
        ).strip().lower()
        if re.search(r"\b(kgs?|kilograms?)\b", unit_text):
            return "kg"
        if re.search(r"\b(pcs?|pieces?|ea|each|unit|units)\b", unit_text):
            return "pc"
        sku = str(part.get("sku") or part.get("part_sku") or part.get("product_sku") or "").strip().upper()
        name = str(part.get("name") or part.get("part_name") or part.get("material_name") or "").strip().upper()
        if sku.startswith("Z-RM"):
            return "kg"
        if " KG" in f" {name} " or "KGS" in name:
            return "kg"
        return "pc"

    def _is_raw_material_job_part(self, part: Optional[Dict[str, Any]]) -> bool:
        if not isinstance(part, dict):
            return False
        sku = str(
            part.get("sku")
            or part.get("part_sku")
            or part.get("product_sku")
            or part.get("material_sku")
            or part.get("part_code")
            or part.get("product_code")
            or part.get("code")
            or ""
        ).strip().upper()
        return sku.startswith("Z-RM")

    def _find_job_part_for_scan_item(self, item: Optional[Dict[str, Any]]) -> Optional[Dict[str, Any]]:
        if not isinstance(item, dict):
            return None
        item_product_id = self._normalize_material_match_key(
            item.get("material_product_id")
            or item.get("product_id")
            or item.get("material_code")
        )
        item_sku = self._normalize_material_match_key(
            item.get("material_sku")
            or item.get("sku")
            or item.get("product_sku")
            or item.get("part_sku")
        )
        for part in self._job_part_rows():
            part_product_id = self._normalize_material_match_key(
                part.get("part_product_id")
                or part.get("product_id")
                or part.get("material_code")
            )
            part_sku = self._normalize_material_match_key(
                part.get("sku")
                or part.get("part_sku")
                or part.get("product_sku")
                or part.get("material_sku")
            )
            if item_product_id and part_product_id and item_product_id == part_product_id:
                return part
            if item_sku and part_sku and item_sku == part_sku:
                return part
        if item_product_id or item_sku:
            # Identified products must match a required part by Product ID or
            # Product SKU. A similar display name is not sufficient.
            return None
        item_keys = self._raw_material_match_keys(item) | self._raw_material_name_keys(item)
        if not item_keys:
            return None
        for part in self._job_part_rows():
            part_keys = self._part_material_match_keys(part) | self._part_material_name_keys(part)
            if item_keys.intersection(part_keys):
                return part
        return None

    def _raw_material_matches_job_parts(self, row: Optional[Dict[str, Any]]) -> bool:
        return self._find_job_part_for_scan_item(row) is not None

    def _linked_job_part_matches(self) -> List[tuple[Dict[str, Any], Dict[str, Any], Dict[str, str]]]:
        """Return parts supplied by the main or a scanned linked job product."""
        s = self.state
        matches: List[tuple[Dict[str, Any], Dict[str, Any], Dict[str, str]]] = []
        seen: Set[str] = set()
        supplying_jobs: List[Dict[str, Any]] = [{
            "job_code": s.job_code,
            "job_name": s.job_name,
            "job_payload": s.job_payload or {},
            "is_main_job": True,
        }]
        if s.linkage_enabled:
            supplying_jobs.extend(row for row in (s.linkage_jobs or []) if isinstance(row, dict))
        for linked in supplying_jobs:
            if not isinstance(linked, dict):
                continue
            payload = linked.get("job_payload") if isinstance(linked.get("job_payload"), dict) else {}
            identity = self._job_product_identity_from_payload(payload)
            linked_id = self._normalize_material_match_key(identity.get("product_id"))
            linked_sku = self._normalize_material_match_key(identity.get("product_sku"))
            if not linked_id and not linked_sku:
                continue
            for part in self._job_part_rows():
                part_id = self._normalize_material_match_key(
                    part.get("part_product_id") or part.get("product_id")
                )
                part_sku = self._normalize_material_match_key(
                    part.get("sku") or part.get("part_sku") or part.get("product_sku")
                )
                id_match = bool(linked_id and part_id and linked_id == part_id)
                sku_match = bool(linked_sku and part_sku and linked_sku == part_sku)
                if not (id_match or sku_match):
                    continue
                match_key = f"{linked_id or linked_sku}|{part_id or part_sku}"
                if match_key in seen:
                    continue
                seen.add(match_key)
                matches.append((linked, part, identity))
        return matches

    def _job_identity_auto_part_keys(self) -> Set[str]:
        """Identify parts supplied by the main or an actually scanned linked job."""
        matched_keys: Set[str] = set()
        for _job, part, _identity in self._linked_job_part_matches():
            for raw in (
                part.get("part_product_id"),
                part.get("product_id"),
                part.get("sku"),
                part.get("part_sku"),
                part.get("product_sku"),
            ):
                key = self._normalize_material_match_key(raw)
                if key:
                    matched_keys.add(key)
        return {key for key in matched_keys if key}

    def _accepted_hooked_pack_qty(self, pack_logs: Optional[List[Dict[str, Any]]] = None) -> float:
        """Total accepted finished-pack quantity mirrored by hooked job parts."""
        total = 0.0
        rows = pack_logs if isinstance(pack_logs, list) else list(self.state.product_pack_history_logs or [])
        for row in rows:
            if not isinstance(row, dict) or bool(row.get("voided")):
                continue
            raw_qty = row.get("completed_pack_qty")
            if raw_qty in (None, ""):
                raw_qty = row.get("qty_q")
            if raw_qty in (None, ""):
                raw_qty = row.get("good_qty")
            if raw_qty in (None, ""):
                raw_qty = row.get("qty")
            total += max(0.0, self._parse_number(raw_qty))
        return total

    def _populate_linked_parts_from_main_pack(
        self,
        pack_hist: Dict[str, Any],
        pack_qty: int,
        raw_scan: str,
    ) -> List[Dict[str, Any]]:
        """Populate only linked-job products that match a main-job part."""
        if not isinstance(pack_hist, dict) or int(pack_qty or 0) <= 0:
            return []
        # Non-P linkage jobs are independent outputs.  Each output has its own
        # PACK QR and may use a different part quantity per finished unit, so a
        # main-job PACK must never manufacture/credit part stock for them.
        if self._multi_output_linkage_enabled():
            return []
        s = self.state
        scanned_job_code = self._extract_job_code_from_pack_qr(raw_scan)
        if not scanned_job_code or scanned_job_code != self._normalize_job_code(s.job_code):
            return []
        pack_key = str(self._pack_history_key(pack_hist) or "").strip()
        rows: List[Dict[str, Any]] = []
        for linked, part, identity in self._linked_job_part_matches():
            linked_job_code = str(linked.get("job_code") or "").strip()
            product_id = str(identity.get("product_id") or part.get("part_product_id") or "").strip()
            product_sku = str(identity.get("product_sku") or part.get("sku") or "").strip()
            product_name = str(
                identity.get("product_name")
                or part.get("name")
                or part.get("part_name")
                or product_sku
                or "Linked Job Part"
            ).strip()
            unique_key = f"LINKAGE_PACK_PART:{linked_job_code}:{product_id or product_sku}:{pack_key}"
            if unique_key in (s.raw_material_unique_keys or set()):
                continue
            per_unit_info = self._resolve_part_qty_per_unit(part)
            per_unit = self._parse_number(per_unit_info.get("value"))
            supplied_qty = max(1, int(round(int(pack_qty or 0) * (per_unit if per_unit > 0 else 1.0))))
            owner_ctx = self._scan_owner_context()
            log_row = {
                "material": product_name,
                "material_name": product_name,
                "material_product_id": product_id or None,
                "material_sku": product_sku or None,
                "qty": supplied_qty,
                "unit": "pc",
                "material_type": "COMPONENT_PART",
                "job_part_name": str(part.get("name") or part.get("part_name") or product_name),
                "job_part_sku": str(part.get("sku") or part.get("part_sku") or product_sku) or None,
                "raw_scan": raw_scan,
                "source": "LINKAGE_MAIN_PACK_AUTO_PART",
                "unique_key": unique_key,
                "linked_job_code": linked_job_code or None,
                "linked_job_name": linked.get("job_name"),
                "required_from_job_code": linked_job_code or None,
                "required_from_job": linked.get("job_name") or linked_job_code or None,
                "matched_by": "product_id" if self._normalize_material_match_key(identity.get("product_id")) == self._normalize_material_match_key(part.get("part_product_id") or part.get("product_id")) else "sku",
                "part_qty_per_unit": per_unit if per_unit > 0 else 1.0,
                "part_qty_per_unit_source": per_unit_info.get("source"),
                "request_part_qty_increment": supplied_qty,
                "auto_populated_from_main_pack": True,
                "index": str(pack_hist.get("index") or "-"),
                "total_labels": str(pack_hist.get("total_labels") or "-"),
                "lot_number": str(pack_hist.get("lot_number") or "-"),
                "po_number": str(pack_hist.get("po_number") or "-"),
                "scanned_at": datetime.now(timezone.utc).isoformat(),
                **owner_ctx,
            }
            s.raw_material_scans.append(product_name)
            s.raw_material_logs.append(log_row)
            s.raw_material_unique_keys.add(unique_key)
            rows.append(log_row)
        if rows:
            pack_hist["linkage_auto_parts"] = rows
        return rows

    def _part_for_raw_material_row(self, row: Optional[Dict[str, Any]]) -> Optional[Dict[str, Any]]:
        raw_name_keys = self._raw_material_name_keys(row)
        raw_match_keys = self._raw_material_match_keys(row)
        owner_code = self._normalize_job_code(
            (row or {}).get("job_code")
            or (row or {}).get("raw_job_code")
            or (row or {}).get("po_number")
        )
        matched_parts: List[Dict[str, Any]] = []
        for part in self._job_part_rows():
            if raw_match_keys and raw_match_keys.intersection(self._part_material_match_keys(part)):
                matched_parts.append(part)
            elif raw_name_keys and raw_name_keys.intersection(self._part_material_name_keys(part)):
                matched_parts.append(part)
        if owner_code:
            owned_part = next(
                (
                    part for part in matched_parts
                    if self._normalize_job_code(part.get("required_from_job_code")) == owner_code
                ),
                None,
            )
            if owned_part is not None:
                return owned_part
        if matched_parts:
            return matched_parts[0]
        all_parts = self._job_part_rows()
        return all_parts[0] if len(all_parts) == 1 else None

    def _raw_logs_for_part(
        self,
        raw_logs: List[Dict[str, Any]],
        part: Optional[Dict[str, Any]],
        *,
        total_part_count: int = 0,
    ) -> List[Dict[str, Any]]:
        rows = [x for x in (raw_logs or []) if isinstance(x, dict)]
        if not rows:
            return []
        part_keys = self._part_material_match_keys(part)
        if not part_keys:
            return rows if total_part_count <= 1 else []
        matched = [row for row in rows if part_keys.intersection(self._raw_material_match_keys(row))]
        part_owner = self._normalize_job_code((part or {}).get("required_from_job_code"))
        if part_owner and matched:
            shared_rows = [
                row for row in matched
                if bool(row.get("shared_part_storage"))
            ]
            explicitly_owned = [
                row for row in matched
                if self._normalize_job_code(
                    row.get("required_from_job_code")
                    or row.get("scanned_raw_job_code")
                    or row.get("raw_job_code")
                ) == part_owner
            ]
            if shared_rows or explicitly_owned:
                matched = shared_rows + [
                    row for row in explicitly_owned if row not in shared_rows
                ]
            elif any(
                self._normalize_job_code(
                    row.get("required_from_job_code")
                    or row.get("scanned_raw_job_code")
                    or row.get("raw_job_code")
                )
                for row in matched
            ):
                matched = []
        return matched if matched or total_part_count > 1 else rows

    def _raw_qty_for_part(
        self,
        raw_logs: List[Dict[str, Any]],
        part: Optional[Dict[str, Any]],
        *,
        total_part_count: int = 0,
    ) -> float:
        rows = self._raw_logs_for_part(raw_logs, part, total_part_count=total_part_count)
        if not rows:
            return 0.0
        return sum(max(0.0, self._parse_number(x.get("qty"))) for x in rows)

    def _raw_consumption_for_part(
        self,
        raw_logs: List[Dict[str, Any]],
        part: Optional[Dict[str, Any]],
        consumed_units: float,
        *,
        total_part_count: int = 0,
        fallback_part_qty_per_unit: float = 0.0,
        pack_logs: Optional[List[Dict[str, Any]]] = None,
    ) -> Dict[str, float]:
        rows = self._raw_logs_for_part(raw_logs, part, total_part_count=total_part_count)
        scanned_qty = sum(
            self._parse_number(row.get("qty"))
            if str(row.get("source") or "").startswith("FINISH_SHIFT_PART_CARRYOVER")
            else max(0.0, self._parse_number(row.get("qty")))
            for row in rows
        )
        part_keys = self._part_material_match_keys(part)
        stamped_pack_used_qty = 0.0
        stamped_pack_units = 0.0
        has_stamped_pack_rows = False
        ownership_locked = False
        part_owner_code = self._normalize_job_code((part or {}).get("required_from_job_code"))
        for pack_row in (pack_logs or []):
            if not isinstance(pack_row, dict) or bool(pack_row.get("voided")):
                continue
            entries = pack_row.get("raw_part_consumption")
            if not isinstance(entries, list):
                continue
            for entry in entries:
                if not isinstance(entry, dict):
                    continue
                entry_owner_code = self._normalize_job_code(entry.get("required_from_job_code"))
                if part_owner_code and entry_owner_code and part_owner_code != entry_owner_code:
                    continue
                entry_keys = self._part_material_match_keys(entry)
                if part_keys and entry_keys and not part_keys.intersection(entry_keys):
                    continue
                if part_keys and not entry_keys and total_part_count > 1:
                    continue
                per_unit = self._parse_number(
                    entry.get("part_qty_per_unit_kg")
                    if entry.get("part_qty_per_unit_kg") not in (None, "")
                    else entry.get("part_qty_per_unit")
                )
                produced = self._parse_number(entry.get("produced_units"))
                used = self._parse_number(
                    entry.get("used_qty_kg")
                    if entry.get("used_qty_kg") not in (None, "")
                    else entry.get("used_qty")
                )
                if bool(entry.get("job_output_locked")):
                    ownership_locked = True
                    has_stamped_pack_rows = True
                if used <= 0 and per_unit > 0 and produced > 0:
                    used = produced * per_unit
                if used <= 0:
                    continue
                has_stamped_pack_rows = True
                stamped_pack_used_qty += used
                stamped_pack_units += max(0.0, produced)
        if has_stamped_pack_rows:
            extra_units = 0.0 if ownership_locked else max(
                0.0,
                float(consumed_units or 0.0) - stamped_pack_units,
            )
            extra_used_qty = 0.0
            fallback_per_unit = max(0.0, float(fallback_part_qty_per_unit or 0.0))
            if extra_units > 0 and fallback_per_unit > 0:
                extra_used_qty = extra_units * fallback_per_unit
            used_qty = stamped_pack_used_qty + extra_used_qty
            return {
                "scanned_qty": scanned_qty,
                "used_qty": used_qty,
                "available_qty": scanned_qty - used_qty,
            }
        remaining_units = max(0.0, float(consumed_units or 0.0))
        used_qty = 0.0
        unit_kind = self._part_unit_kind(part)
        for row in rows:
            row_qty = max(0.0, self._parse_number(row.get("qty")))
            if row_qty <= 0:
                continue
            if unit_kind == "kg":
                row_source = str(row.get("part_qty_per_unit_source") or "").strip().lower()
                part_qty_per_unit = self._parse_number(row.get("part_qty_per_unit_kg")) if row_source == "app" else 0.0
                if row_source == "app" and part_qty_per_unit <= 0:
                    part_qty_per_unit = self._parse_number(row.get("part_qty_per_unit_grams")) / 1000.0
            else:
                part_qty_per_unit = self._parse_number(row.get("part_qty_per_unit"))
            if part_qty_per_unit <= 0:
                part_qty_per_unit = max(0.0, float(fallback_part_qty_per_unit or 0.0))
            if part_qty_per_unit <= 0:
                continue
            row_units_capacity = row_qty / part_qty_per_unit
            units_used = min(remaining_units, row_units_capacity)
            if units_used <= 0:
                break
            used_qty += min(row_qty, units_used * part_qty_per_unit)
            remaining_units -= units_used
        fallback_per_unit = max(0.0, float(fallback_part_qty_per_unit or 0.0))
        if remaining_units > 0 and fallback_per_unit > 0:
            used_qty += remaining_units * fallback_per_unit
        return {
            "scanned_qty": scanned_qty,
            "used_qty": used_qty,
            "available_qty": scanned_qty - used_qty,
        }

    def _pack_raw_consumption_entries(
        self,
        qty: Any,
        job_output_qty: Optional[Dict[str, Any]] = None,
    ) -> List[Dict[str, Any]]:
        try:
            produced_qty = max(0, int(qty or 0))
        except Exception:
            produced_qty = 0
        if produced_qty <= 0:
            return []
        entries: List[Dict[str, Any]] = []
        for part in self._job_part_rows():
            owner_job_code = self._normalize_job_code(part.get("required_from_job_code"))
            owner_locked = isinstance(job_output_qty, dict) and bool(job_output_qty)
            owner_produced_qty = produced_qty
            if owner_locked:
                owner_produced_qty = max(0, int(job_output_qty.get(owner_job_code, 0) or 0))
            info = self._resolve_part_qty_per_unit(part)
            unit_kind = self._part_unit_kind(part)
            per_unit = float(info.get("value") or 0.0)
            source = str(info.get("source") or "").strip().lower()
            is_weight = unit_kind == "kg"
            pending_weight = is_weight and source != "app"
            refresh_pending = bool(
                is_weight
                and source == "app"
                and self.state.external_average_weight_needs_refresh
            )
            used_qty = owner_produced_qty * per_unit
            entries.append(
                {
                    "sku": part.get("sku") or part.get("part_sku") or part.get("product_sku") or None,
                    "name": part.get("name") or part.get("part_name") or part.get("material_name") or None,
                    "part_product_id": part.get("part_product_id") or part.get("product_id") or None,
                    "unit": unit_kind,
                    "part_qty_per_unit": per_unit,
                    "part_qty_per_unit_kg": per_unit if is_weight else None,
                    "part_qty_per_unit_grams": per_unit * 1000.0 if is_weight else None,
                    "part_qty_per_unit_source": source or "standard",
                    "standard_pending_weight": pending_weight,
                    "weight_refresh_pending": refresh_pending,
                    "temporary_weight": bool(pending_weight or refresh_pending),
                    "weight_label": (
                        "DEFAULT WEIGHT" if pending_weight
                        else (
                            "LAST SENT WEIGHT - NEW WEIGHT PENDING"
                            if is_weight and bool(self.state.external_average_weight_needs_refresh)
                            else ("SENT WEIGHT" if is_weight else "JOB API QTY")
                        )
                    ),
                    "weight_received_at": (
                        None if pending_weight or not is_weight
                        else self.state.external_average_weight_received_at
                    ),
                    "produced_units": owner_produced_qty,
                    "required_from_job": part.get("required_from_job"),
                    "required_from_job_code": owner_job_code or None,
                    "job_output_locked": owner_locked,
                    "used_qty": used_qty,
                    "used_qty_kg": used_qty if is_weight else None,
                    "weight_needs_refresh": bool(
                        is_weight and self.state.external_average_weight_needs_refresh
                    ),
                }
            )
        return entries

    def _stamp_pack_raw_consumption(
        self,
        pack_hist: Optional[Dict[str, Any]],
        qty: Any,
        job_output_qty: Optional[Dict[str, Any]] = None,
    ) -> None:
        if not isinstance(pack_hist, dict):
            return
        entries = self._pack_raw_consumption_entries(qty, job_output_qty=job_output_qty)
        if not entries:
            return
        pack_hist["raw_part_consumption"] = entries
        first = next(
            (entry for entry in entries if str(entry.get("unit") or "").lower() == "kg"),
            entries[0],
        )
        pack_hist["raw_part_qty_per_unit_kg"] = first.get("part_qty_per_unit_kg")
        pack_hist["raw_part_qty_per_unit_grams"] = first.get("part_qty_per_unit_grams")
        pack_hist["raw_part_qty_per_unit_source"] = first.get("part_qty_per_unit_source")
        pack_hist["raw_part_qty_standard_pending_weight"] = bool(first.get("standard_pending_weight"))
        pack_hist["raw_part_qty_weight_refresh_pending"] = bool(
            first.get("weight_refresh_pending")
        )

    def _apply_weight_to_standard_pack_consumption(self, grams: float) -> int:
        kg_value = float(grams or 0.0) / 1000.0
        if kg_value <= 0:
            return 0
        changed = 0
        s = self.state
        for row in (s.product_pack_history_logs or []):
            if not isinstance(row, dict):
                continue
            entries = row.get("raw_part_consumption")
            if not isinstance(entries, list):
                continue
            row_changed = False
            for entry in entries:
                if not isinstance(entry, dict) or not (
                    bool(entry.get("standard_pending_weight"))
                    or bool(entry.get("weight_refresh_pending"))
                ):
                    continue
                produced_units = self._parse_number(entry.get("produced_units"))
                entry["standard_part_qty_per_unit_kg"] = entry.get("part_qty_per_unit_kg")
                entry["temporary_part_qty_per_unit_kg"] = entry.get("part_qty_per_unit_kg")
                entry["part_qty_per_unit_kg"] = kg_value
                entry["part_qty_per_unit_grams"] = float(grams or 0.0)
                entry["part_qty_per_unit_source"] = "app"
                entry["standard_pending_weight"] = False
                entry["weight_refresh_pending"] = False
                entry["temporary_weight"] = False
                entry["weight_label"] = "SENT WEIGHT"
                entry["weight_received_at"] = self.state.external_average_weight_received_at
                entry["default_weight_replaced_at"] = datetime.now(timezone.utc).isoformat()
                entry["used_qty_kg"] = produced_units * kg_value
                entry["used_qty"] = produced_units * kg_value
                row_changed = True
            if row_changed:
                first = next(
                    (
                        entry for entry in entries
                        if isinstance(entry, dict) and str(entry.get("unit") or "").lower() == "kg"
                    ),
                    next((entry for entry in entries if isinstance(entry, dict)), {}),
                )
                row["raw_part_qty_per_unit_kg"] = first.get("part_qty_per_unit_kg")
                row["raw_part_qty_per_unit_grams"] = first.get("part_qty_per_unit_grams")
                row["raw_part_qty_per_unit_source"] = first.get("part_qty_per_unit_source")
                row["raw_part_qty_standard_pending_weight"] = False
                row["raw_part_qty_weight_refresh_pending"] = False
                changed += 1
        return changed

    def _apply_weight_to_standard_raw_material_logs(self, grams: float) -> int:
        kg_value = float(grams or 0.0) / 1000.0
        if kg_value <= 0:
            return 0
        changed = 0
        for row in (self.state.raw_material_logs or []):
            if not isinstance(row, dict):
                continue
            if str(row.get("unit") or "").strip().lower() != "kg":
                continue
            source = str(row.get("part_qty_per_unit_source") or "").strip().lower()
            refresh_pending = bool(row.get("weight_refresh_pending"))
            if source == "app" and not refresh_pending:
                continue
            row["standard_part_qty_per_unit_kg"] = row.get("part_qty_per_unit_kg")
            row["temporary_part_qty_per_unit_kg"] = row.get("part_qty_per_unit_kg")
            row["part_qty_per_unit_kg"] = kg_value
            row["part_qty_per_unit_grams"] = float(grams or 0.0)
            row["part_qty_per_unit_source"] = "app"
            row["weight_refresh_pending"] = False
            row["temporary_weight"] = False
            row["part_qty_per_unit_weight_applied_at"] = datetime.now(timezone.utc).isoformat()
            changed += 1
        return changed

    def _pack_blocked_by_missing_part_availability(
        self,
        pack_qty: Any = 0,
        job_output_qty: Optional[Dict[str, Any]] = None,
    ) -> Optional[str]:
        self._pending_pack_depletion_grace_keys = []
        restriction_enabled = bool(
            self.client_config.get("product_part_restriction_enabled", True)
        )
        statuses = self._current_part_availability_statuses()
        threshold_pct = min(100.0, max(0.0, float(self.client_config.get("part_availability_warning_threshold_percent", 10.0) or 0.0)))
        threshold_ratio = threshold_pct / 100.0
        incoming_entries = self._pack_raw_consumption_entries(
            pack_qty,
            job_output_qty=job_output_qty,
        )
        for row in statuses:
            row_keys = set(row.get("keys") or set())
            row_owner = self._normalize_job_code(row.get("required_from_job_code"))
            incoming_used = 0.0
            for entry in incoming_entries:
                if not isinstance(entry, dict):
                    continue
                entry_owner = self._normalize_job_code(entry.get("required_from_job_code"))
                if row_owner and entry_owner and row_owner != entry_owner:
                    continue
                entry_keys = (
                    self._part_material_match_keys(entry)
                    | self._part_material_name_keys(entry)
                )
                if row_keys and entry_keys and not row_keys.intersection(entry_keys):
                    continue
                incoming_used += max(
                    0.0,
                    self._parse_number(
                        entry.get("used_qty_kg")
                        if entry.get("used_qty_kg") not in (None, "")
                        else entry.get("used_qty")
                    ),
                )
            row["incoming_used_qty"] = incoming_used
            row["projected_available_qty"] = (
                float(row.get("available_qty") or 0.0) - incoming_used
            )

        over_limit = (
            [
                row for row in statuses
                if (
                    float(row.get("incoming_used_qty") or 0.0) > 0
                    and float(row.get("projected_available_qty") or 0.0) < -1e-9
                )
            ]
            if restriction_enabled
            else []
        )
        low = [
            row for row in statuses
            if (
                float(row.get("scanned_qty") or 0.0) > 0
                and (
                    float(row.get("projected_available_qty") or 0.0)
                    / float(row.get("scanned_qty") or 1.0)
                ) <= threshold_ratio
            )
            or (
                not restriction_enabled
                and float(row.get("projected_available_qty") or 0.0) < 0
            )
        ]
        if not over_limit and not low:
            self._product_parts_missing_names = []
            self._product_parts_missing_keys = set()
            self._hide_product_parts_missing_error()
            return None
        warning_rows = over_limit or low
        warning_names = [str(row.get("name") or "part") for row in warning_rows]
        warning_keys: Set[str] = set()
        for row in warning_rows:
            warning_keys.update(row.get("keys") or set())
        self._product_parts_missing_names = warning_names
        self._product_parts_missing_keys = warning_keys
        shown = ", ".join(warning_names[:2]) + (f" (+{len(warning_names) - 2})" if len(warning_names) > 2 else "")
        if low and not over_limit:
            self._show_product_parts_missing_error(
                shown,
                message=f"LOW PRODUCT PART: {shown} has {threshold_pct:g}% or less remaining. Scan more product parts soon.",
            )
            return None

        self._show_product_parts_missing_error(
            shown,
            message=(
                f"PACK BLOCKED: {shown} has zero/insufficient product-part "
                "balance for this pack. Scan more product parts."
            ),
        )
        return shown

    def _build_part_availability_carryover_logs(self) -> List[Dict[str, Any]]:
        """Snapshot only unused part quantities for a same-job next shift."""
        s = self.state
        parts = self._job_part_rows()
        raw_logs = [row for row in (s.raw_material_logs or []) if isinstance(row, dict)]
        produced_units = self._raw_consumption_unit_count({
            "good_total": s.good_total,
            "butal_total": s.butal_total,
            "reject_total": s.reject_total,
            "startup_reject_total": s.startup_reject_total,
            "no_shot_total": s.no_shot_total,
        })
        carry_rows: List[Dict[str, Any]] = []
        seen: Set[str] = set()
        auto_part_keys = self._job_identity_auto_part_keys()
        for part in parts:
            part_keys_all = self._part_material_match_keys(part)
            if auto_part_keys.intersection(part_keys_all):
                # A part produced by the running/main or hooked linked job is
                # created and consumed with the finished pack. It has no
                # scanned stock balance to carry into the next shift.
                continue
            part_keys = self._part_material_match_keys(part)
            part_key = sorted(part_keys)[0] if part_keys else ""
            if part_key and part_key in seen:
                continue
            info = self._resolve_part_qty_per_unit(part)
            consumption = self._raw_consumption_for_part(
                raw_logs,
                part,
                produced_units,
                total_part_count=len(parts),
                fallback_part_qty_per_unit=float(info.get("value") or 0.0),
                pack_logs=s.product_pack_history_logs,
            )
            available = float(consumption.get("available_qty") or 0.0)
            if abs(available) <= 1e-12:
                continue
            matched_logs = self._raw_logs_for_part(raw_logs, part, total_part_count=len(parts))
            source_row = dict(matched_logs[-1]) if matched_logs else {}
            product_id = str(part.get("part_product_id") or part.get("product_id") or source_row.get("material_product_id") or "").strip()
            sku = str(part.get("sku") or part.get("part_sku") or source_row.get("material_sku") or "").strip()
            name = str(part.get("name") or part.get("part_name") or source_row.get("material_name") or sku or "Job Part").strip()
            source_row.update({
                "material": name,
                "material_name": name,
                "material_product_id": product_id or None,
                "material_sku": sku or None,
                "job_part_name": name,
                "job_part_sku": sku or None,
                "qty": available,
                "source": "FINISH_SHIFT_PART_CARRYOVER",
                "unique_key": f"SHIFT-CARRY:{self._normalize_job_code(s.job_code)}:{product_id or sku}:{datetime.now(timezone.utc).isoformat()}",
                "carryover_from_job_code": str(s.job_code or ""),
                "carryover_available_qty": available,
                "carried_at_utc": datetime.now(timezone.utc).isoformat(),
            })
            carry_rows.append(source_row)
            if part_key:
                seen.add(part_key)
        return carry_rows

    def _shift_carryover_key(self, machine_code: Any, job_code: Any) -> str:
        machine = str(machine_code or "").strip().upper()
        job = self._normalize_job_code(job_code)
        return f"{machine}|{job}" if machine and job else ""

    def _save_shift_carryover_record(self, shift_payload: Dict[str, Any]) -> bool:
        """Replace the small carryover balance for exactly one machine/job."""
        payload = dict(shift_payload or {})
        machine_code = str(payload.get("machine_code") or self.state.machine_code or "").strip()
        job_code = str(payload.get("job_code") or self.state.job_code or "").strip()
        key = self._shift_carryover_key(machine_code, job_code)
        if not key:
            return False
        part_rows = [
            dict(row) for row in (payload.get("part_availability_carryover_logs") or [])
            if isinstance(row, dict)
        ]
        butal: Dict[str, Any] = {}
        record = {
            "key": key,
            "client_id": self._current_client_id(),
            "machine_code": machine_code,
            "job_code": job_code,
            "job_name": payload.get("job_name") or self.state.job_name,
            "part_availability_carryover_logs": part_rows,
            "butal_carryover": butal,
            "external_average_weight_grams": payload.get("external_average_weight_grams"),
            "external_average_weight_unit": payload.get("external_average_weight_unit"),
            "external_average_weight_received_at": payload.get("external_average_weight_received_at"),
            "external_average_weight_sent_at": payload.get("external_average_weight_sent_at"),
            "external_average_weight_source": payload.get("external_average_weight_source"),
            "external_average_weight_sender": payload.get("external_average_weight_sender"),
            "saved_at_utc": datetime.now(timezone.utc).isoformat(),
        }
        rows = [
            row for row in _load_shift_carryover_json()
            if self._shift_carryover_key(row.get("machine_code"), row.get("job_code")) != key
        ]
        # An empty balance supersedes and removes any older carryover for this
        # machine/job instead of letting stale stock return in a later shift.
        has_weight = self._parse_number(record.get("external_average_weight_grams")) > 0
        if part_rows or butal or has_weight:
            rows.append(record)
        return _save_shift_carryover_json(rows)

    def _clear_shift_carryover_record(self, machine_code: Any, job_code: Any) -> None:
        key = self._shift_carryover_key(machine_code, job_code)
        if not key:
            return
        rows = _load_shift_carryover_json()
        kept = [
            row for row in rows
            if self._shift_carryover_key(row.get("machine_code"), row.get("job_code")) != key
        ]
        if len(kept) != len(rows):
            _save_shift_carryover_json(kept)

    def _restore_same_job_part_carryover(self) -> int:
        """Restore same-job part stock and the last weight as temporary."""
        s = self.state
        machine_code = str(s.machine_code or "").strip()
        job_code = self._normalize_job_code(s.job_code)
        if not machine_code or not job_code:
            return 0
        candidates = [
            row for row in _load_shift_carryover_json()
            if isinstance(row, dict)
            and str(row.get("machine_code") or "").strip() == machine_code
            and self._normalize_job_code(row.get("job_code")) == job_code
            and isinstance(row.get("part_availability_carryover_logs"), list)
        ]
        # One-time compatibility fallback for shifts saved before the dedicated
        # carryover store existed.
        if not candidates:
            candidates = [
            row for row in _load_finish_shift_json()
            if isinstance(row, dict)
            and str(row.get("machine_code") or "").strip() == machine_code
            and self._normalize_job_code(row.get("job_code")) == job_code
            and isinstance(row.get("part_availability_carryover_logs"), list)
            ]
        if not candidates:
            return 0
        candidates.sort(key=lambda row: str(row.get("finished_at_utc") or row.get("ended_at_utc") or ""))
        latest = candidates[-1]
        current_parts = [row for row in self._job_part_rows() if isinstance(row, dict)]
        allowed_part_keys: Set[str] = set()
        for part in current_parts:
            allowed_part_keys.update(self._part_material_match_keys(part))
            allowed_part_keys.update(self._part_material_name_keys(part))
        # Never trust carryover rows merely because their parent finish-shift
        # record has the same job code.  Revalidate every material against the
        # freshly loaded job parts so contaminated/legacy rows cannot cross
        # into the new shift.
        rows: List[Dict[str, Any]] = []
        if allowed_part_keys:
            for raw_row in latest.get("part_availability_carryover_logs") or []:
                if not isinstance(raw_row, dict):
                    continue
                row_keys = self._raw_material_match_keys(raw_row)
                row_keys.update(self._part_material_name_keys(raw_row))
                if allowed_part_keys.intersection(row_keys):
                    rows.append(dict(raw_row))

        # A continued shift may use the last confirmed weighing-app value
        # immediately, but it remains temporary until a genuinely newer value
        # arrives. Keeping the previous timestamps lets server polling reject
        # the unchanged pre-finish-shift value.
        carried_weight_grams = self._parse_number(latest.get("external_average_weight_grams"))
        if carried_weight_grams <= 0:
            for pack_row in reversed(latest.get("product_pack_history_logs") or []):
                if not isinstance(pack_row, dict):
                    continue
                for entry in reversed(pack_row.get("raw_part_consumption") or []):
                    if not isinstance(entry, dict):
                        continue
                    if str(entry.get("unit") or "").strip().lower() != "kg":
                        continue
                    candidate_grams = self._parse_number(entry.get("part_qty_per_unit_grams"))
                    if candidate_grams > 0 and not bool(entry.get("temporary_weight")):
                        carried_weight_grams = candidate_grams
                        break
                if carried_weight_grams > 0:
                    break
        if carried_weight_grams > 0:
            carried_weight_kg = carried_weight_grams / 1000.0
            s.external_average_weight_grams = carried_weight_grams
            s.external_average_weight_unit = str(latest.get("external_average_weight_unit") or "g")
            s.external_average_weight_received_at = latest.get("external_average_weight_received_at")
            s.external_average_weight_sent_at = latest.get("external_average_weight_sent_at")
            s.external_average_weight_source = str(
                latest.get("external_average_weight_source") or "finish_shift_carryover"
            )
            s.external_average_weight_sender = latest.get("external_average_weight_sender")
            s.external_average_weight_needs_refresh = True
            for row in rows:
                if str(row.get("unit") or "").strip().lower() != "kg":
                    continue
                row["part_qty_per_unit_kg"] = carried_weight_kg
                row["part_qty_per_unit_grams"] = carried_weight_grams
                row["part_qty_per_unit_source"] = "app"
                row["weight_refresh_pending"] = True
                row["temporary_weight"] = True
                row["weight_label"] = "LAST SENT WEIGHT - NEW WEIGHT PENDING"
                row["carried_weight_from_previous_shift"] = True
        if not rows:
            return 0
        s.raw_material_logs = rows
        s.raw_material_scans = [str(row.get("material_name") or row.get("material") or "Job Part") for row in rows]
        s.raw_material_unique_keys = {str(row.get("unique_key") or "").strip() for row in rows if str(row.get("unique_key") or "").strip()}
        s.raw_sacks_count = len(rows)
        return len(rows)

    def _current_part_availability_statuses(self) -> List[Dict[str, Any]]:
        # Every required job part must have available scanned quantity: raw
        # resin, bodies, covers, stickers, polybags, and other components.
        # A product matching the main job or an actually scanned linked job is
        # recorded automatically at its requested quantity and is exempt.
        part_rows = list(self._job_part_rows())
        if not part_rows:
            return []
        auto_part_keys = self._job_identity_auto_part_keys()
        raw_logs = [x for x in (self.state.raw_material_logs or []) if isinstance(x, dict)]
        produced_units = self._raw_consumption_unit_count(
            {
                "good_total": self.state.good_total,
                "butal_total": self.state.butal_total,
                "reject_total": self.state.reject_total,
                "startup_reject_total": self.state.startup_reject_total,
                "no_shot_total": self.state.no_shot_total,
            }
        )
        statuses: List[Dict[str, Any]] = []
        for part in part_rows:
            part_match_keys = self._part_material_match_keys(part) | self._part_material_name_keys(part)
            if auto_part_keys.intersection(part_match_keys):
                continue
            part_qty_info = self._resolve_part_qty_per_unit(part)
            raw_consumption = self._raw_consumption_for_part(
                raw_logs,
                part,
                produced_units,
                total_part_count=len(part_rows),
                fallback_part_qty_per_unit=float(part_qty_info.get("value") or 0.0),
                pack_logs=self.state.product_pack_history_logs,
            )
            keys = part_match_keys
            matching_logs = self._raw_logs_for_part(raw_logs, part, total_part_count=len(part_rows))
            latest_part_scan = max(
                (str(row.get("scanned_at") or row.get("carried_at_utc") or "") for row in matching_logs),
                default="",
            )
            storage_key = self._normalize_material_match_key(
                part.get("sku")
                or part.get("part_sku")
                or part.get("product_sku")
                or part.get("part_product_id")
                or part.get("product_id")
                or part.get("name")
                or part.get("part_name")
            )
            statuses.append({
                "name": str(
                    part.get("sku")
                    or part.get("part_sku")
                    or part.get("product_sku")
                    or part.get("name")
                    or part.get("part_name")
                    or "part"
                ).strip() or "part",
                "keys": {key for key in keys if key},
                "storage_key": storage_key,
                "required_from_job_code": self._normalize_job_code(
                    part.get("required_from_job_code")
                ),
                "scanned_qty": float(raw_consumption.get("scanned_qty") or 0.0),
                "used_qty": float(raw_consumption.get("used_qty") or 0.0),
                "available_qty": float(raw_consumption.get("available_qty") or 0.0),
                "latest_part_scan": latest_part_scan,
            })
        if self._shared_product_part_storage_enabled():
            shared_rows: Dict[str, Dict[str, Any]] = {}
            for row in statuses:
                key = str(row.get("storage_key") or "").strip()
                if not key:
                    key = "|".join(sorted(str(x) for x in (row.get("keys") or set())))
                existing = shared_rows.get(key)
                if existing is None:
                    existing = dict(row)
                    existing["required_from_job_code"] = ""
                    existing["required_from_job_codes"] = [
                        row.get("required_from_job_code")
                    ] if row.get("required_from_job_code") else []
                    shared_rows[key] = existing
                    continue
                existing["keys"] = set(existing.get("keys") or set()) | set(row.get("keys") or set())
                existing["scanned_qty"] = max(
                    float(existing.get("scanned_qty") or 0.0),
                    float(row.get("scanned_qty") or 0.0),
                )
                existing["used_qty"] = (
                    float(existing.get("used_qty") or 0.0)
                    + float(row.get("used_qty") or 0.0)
                )
                owner = str(row.get("required_from_job_code") or "").strip()
                if owner and owner not in existing["required_from_job_codes"]:
                    existing["required_from_job_codes"].append(owner)
                existing["available_qty"] = (
                    float(existing.get("scanned_qty") or 0.0)
                    - float(existing.get("used_qty") or 0.0)
                )
                existing["latest_part_scan"] = max(
                    str(existing.get("latest_part_scan") or ""),
                    str(row.get("latest_part_scan") or ""),
                )
            for existing in shared_rows.values():
                storage_keys = set(existing.get("keys") or set())
                storage_logs = [
                    row for row in raw_logs
                    if storage_keys.intersection(self._raw_material_match_keys(row))
                ]
                existing["scanned_qty"] = sum(
                    max(0.0, self._parse_number(row.get("qty")))
                    for row in storage_logs
                )
                existing["available_qty"] = (
                    float(existing.get("scanned_qty") or 0.0)
                    - float(existing.get("used_qty") or 0.0)
                )
            statuses = list(shared_rows.values())
        return statuses

    def _current_missing_part_availability(self) -> tuple[List[str], Set[str]]:
        missing_names: List[str] = []
        missing_keys: Set[str] = set()
        for row in self._current_part_availability_statuses():
            if float(row.get("available_qty") or 0.0) <= 0:
                missing_names.append(str(row.get("name") or "part"))
                missing_keys.update(row.get("keys") or set())
        return missing_names, missing_keys

    def _set_product_parts_error_style(self, blink_on: bool = False):
        if not hasattr(self, "jobPartsInlineError") or self.jobPartsInlineError is None:
            return
        if blink_on:
            self.jobPartsInlineError.setStyleSheet(
                "QLabel#ProductPartsInlineError {"
                " background: rgba(250,204,21,0.98);"
                " color: #111827;"
                " border-top: 2px solid rgba(127,29,29,0.95);"
                " padding: 7px 10px;"
                " font-size: 12px;"
                " font-weight: 900;"
                "}"
            )
        else:
            self.jobPartsInlineError.setStyleSheet(
                "QLabel#ProductPartsInlineError {"
                " background: rgba(127,29,29,0.92);"
                " color: #fff7ed;"
                " border-top: 1px solid rgba(254,202,202,0.65);"
                " padding: 7px 10px;"
                " font-size: 12px;"
                " font-weight: 900;"
                "}"
            )

    def _hide_product_parts_missing_error(self):
        if hasattr(self, "productPartsErrorBlinkTimer") and self.productPartsErrorBlinkTimer is not None:
            self.productPartsErrorBlinkTimer.stop()
        self._product_parts_error_blink_remaining = 0
        self._product_parts_error_blink_on = False
        if hasattr(self, "jobPartsInlineError") and self.jobPartsInlineError is not None:
            self._set_product_parts_error_style(False)
            self.jobPartsInlineError.hide()
        self._apply_product_parts_missing_highlight(False)

    def _tick_product_parts_error_blink(self):
        if not hasattr(self, "jobPartsInlineError") or self.jobPartsInlineError is None:
            return
        remaining = int(getattr(self, "_product_parts_error_blink_remaining", 0) or 0)
        if remaining <= 0:
            self.productPartsErrorBlinkTimer.stop()
            self._product_parts_error_blink_on = False
            self._set_product_parts_error_style(False)
            self._apply_product_parts_missing_highlight(True)
            return
        self._product_parts_error_blink_remaining = remaining - 1
        self._product_parts_error_blink_on = not bool(getattr(self, "_product_parts_error_blink_on", False))
        self._set_product_parts_error_style(self._product_parts_error_blink_on)
        self._apply_product_parts_missing_highlight(self._product_parts_error_blink_on)

    def _apply_product_parts_missing_highlight(self, blink_on: Optional[bool] = None):
        if not hasattr(self, "jobPartsTable") or self.jobPartsTable is None:
            return
        missing = set(getattr(self, "_product_parts_missing_keys", set()) or set())
        if not missing:
            blink_on = False
        if blink_on is None:
            blink_on = bool(getattr(self, "_product_parts_error_blink_on", False)) or bool(missing)
        warn_bg = QBrush(QColor(127, 29, 29, 215))
        warn_fg = QBrush(QColor(255, 247, 237))
        clear_bg = QBrush()
        clear_fg = QBrush()
        for row in range(int(self.jobPartsTable.rowCount() or 0)):
            row_keys = set()
            for col in (0,):
                item = self.jobPartsTable.item(row, col)
                if item is not None:
                    key = self._normalize_material_match_key(item.text())
                    if key:
                        row_keys.add(key)
            row_missing = bool(row_keys.intersection(missing))
            for col in range(int(self.jobPartsTable.columnCount() or 0)):
                item = self.jobPartsTable.item(row, col)
                if item is not None:
                    if row_missing and blink_on:
                        item.setBackground(warn_bg)
                        item.setForeground(warn_fg)
                    else:
                        item.setBackground(clear_bg)
                        item.setForeground(clear_fg)

    def _sync_product_parts_missing_error_after_refresh(self):
        statuses = self._current_part_availability_statuses()
        threshold_pct = min(100.0, max(0.0, float(self.client_config.get("part_availability_warning_threshold_percent", 10.0) or 0.0)))
        threshold_ratio = threshold_pct / 100.0
        warning_rows = [
            row for row in statuses
            if float(row.get("available_qty") or 0.0) <= 0
            or (
                float(row.get("scanned_qty") or 0.0) > 0
                and (float(row.get("available_qty") or 0.0) / float(row.get("scanned_qty") or 1.0)) <= threshold_ratio
            )
        ]
        if not warning_rows:
            self._hide_product_parts_missing_error()
            return
        missing_names = [str(row.get("name") or "part") for row in warning_rows]
        missing_keys: Set[str] = set()
        for row in warning_rows:
            missing_keys.update(row.get("keys") or set())
        self._product_parts_missing_names = missing_names
        self._product_parts_missing_keys = missing_keys
        if hasattr(self, "jobPartsInlineError") and self.jobPartsInlineError is not None:
            shown = ", ".join(missing_names[:2])
            if len(missing_names) > 2:
                shown += f" (+{len(missing_names) - 2})"
            restriction_enabled = bool(
                self.client_config.get("product_part_restriction_enabled", True)
            )
            if (
                restriction_enabled
                and any(float(row.get("available_qty") or 0.0) <= 0 for row in warning_rows)
            ):
                self.jobPartsInlineError.setText(
                    f"PACK LIMIT REACHED: {shown} is zero or negative. Scan the product part to scan more PACK."
                )
            else:
                self.jobPartsInlineError.setText(
                    f"LOW PRODUCT PART: {shown} has {threshold_pct:g}% or less remaining. Scan more product parts soon."
                )
            self.jobPartsInlineError.show()
        self._apply_product_parts_missing_highlight()

    def _show_product_parts_missing_error(self, missing_part: str, *, message: Optional[str] = None):
        msg = str(message or f"Scan parts first: {missing_part} has no available quantity.")
        if hasattr(self, "jobPartsInlineError") and self.jobPartsInlineError is not None:
            self.jobPartsInlineError.setText(msg)
            self._set_product_parts_error_style(True)
            self.jobPartsInlineError.show()
        self._product_parts_error_blink_remaining = 8
        self._product_parts_error_blink_on = True
        if hasattr(self, "productPartsErrorBlinkTimer") and self.productPartsErrorBlinkTimer is not None:
            self.productPartsErrorBlinkTimer.stop()
            self.productPartsErrorBlinkTimer.start(220)
        self._apply_product_parts_missing_highlight(True)

    def _record_job_part_scan(
        self,
        *,
        part: Dict[str, Any],
        material_name: str,
        qty: int,
        raw_scan: str,
        unique_key: str = "",
        source: str = "JOB_PART_QR",
        material_product_id: Optional[str] = None,
        material_sku: Optional[str] = None,
        pack_hist: Optional[Dict[str, Any]] = None,
        raw_job_code: Optional[str] = None,
        shared_storage: bool = False,
    ) -> bool:
        s = self.state
        unique_key = str(unique_key or "").strip()
        if unique_key and unique_key in (s.raw_material_unique_keys or set()):
            self.status.setText("Invalid PART QR: duplicate serial already scanned.")
            self._show_invalid_overlay("PART QR serial already scanned.")
            return True
        unit_kind = self._part_unit_kind(part)
        part_qty_info = self._resolve_part_qty_per_unit(part)
        part_name = str(part.get("name") or part.get("part_name") or material_name or "Job Part").strip() or "Job Part"
        part_sku = str(part.get("sku") or part.get("part_sku") or material_sku or "").strip()
        owner_ctx = self._scan_owner_context()
        log_row = {
            "material": material_name,
            "material_name": material_name,
            "material_product_id": material_product_id or None,
            "material_sku": material_sku or part_sku or None,
            "qty": int(qty or 0),
            "unit": unit_kind,
            "material_type": "RAW_MATERIAL" if unit_kind == "kg" else "COMPONENT_PART",
            "job_part_name": part_name,
            "job_part_sku": part_sku or None,
            "required_from_job": None if shared_storage else part.get("required_from_job"),
            "required_from_job_code": (
                None
                if shared_storage
                else self._normalize_job_code(part.get("required_from_job_code")) or None
            ),
            "shared_part_storage": bool(shared_storage),
            "raw_scan": raw_scan,
            "source": source,
            "unique_key": unique_key or None,
            "raw_job_code": raw_job_code,
            "part_qty_per_unit_kg": float(part_qty_info.get("value") or 0.0),
            "part_qty_per_unit_grams": (
                float(part_qty_info.get("value") or 0.0) * 1000.0
                if str(part_qty_info.get("source") or "").strip().lower() == "app"
                else None
            ),
            "part_qty_per_unit_source": part_qty_info.get("source"),
            "weight_refresh_pending": bool(
                unit_kind == "kg"
                and str(part_qty_info.get("source") or "").strip().lower() == "app"
                and s.external_average_weight_needs_refresh
            ),
            "temporary_weight": bool(
                unit_kind == "kg"
                and (
                    str(part_qty_info.get("source") or "").strip().lower() != "app"
                    or s.external_average_weight_needs_refresh
                )
            ),
            "raw_consumption_units_at_scan": self._raw_consumption_unit_count(
                {
                    "good_total": s.good_total,
                    "butal_total": s.butal_total,
                    "reject_total": s.reject_total,
                    "startup_reject_total": s.startup_reject_total,
                    "no_shot_total": s.no_shot_total,
                }
            ),
            "scanned_at": datetime.now(timezone.utc).isoformat(),
            **owner_ctx,
        }
        if isinstance(pack_hist, dict):
            log_row.update(
                {
                    "index": str(pack_hist.get("index") or "-"),
                    "total_labels": str(pack_hist.get("total_labels") or "-"),
                    "lot_number": str(pack_hist.get("lot_number") or "-"),
                    "po_number": str(pack_hist.get("po_number") or "-"),
                }
            )
        s.raw_sacks_count += 1
        s.raw_material_scans.append(material_name)
        s.raw_material_logs.append(log_row)
        if unique_key:
            s.raw_material_unique_keys.add(unique_key)
        label = "Raw material" if unit_kind == "kg" else "Component part"
        self.status.setText(f"{label} scanned: {material_name} (+{qty})")
        self._refresh_ui()
        material_event_label = f"{label.upper()} SCANNED"
        if part_sku:
            material_event_label += f" | SKU {part_sku}"
        elif material_name:
            material_event_label += f" | {material_name}"
        material_event_label += f" | QTY {qty}"
        self.push_event(
            {
                "type": "RAW_MATERIAL",
                "qty": int(qty or 0),
                "material": material_name,
                "source": source,
                "unit": unit_kind,
                "raw_material_log": log_row,
                "unique_key": unique_key or None,
                "raw_job_code": raw_job_code or None,
            },
            material_event_label,
        )
        return True

    def _reject_multiplier_value(self) -> int:
        raw = str(self.state.reject_multiplier_input or "").strip()
        if not raw:
            return 1
        try:
            return max(1, int(raw))
        except Exception:
            return 1

    def _clear_reject_multiplier(self):
        self.state.reject_multiplier_input = ""

    def _append_reject_multiplier_digit(self, digit: str) -> bool:
        d = str(digit or "").strip()
        if len(d) != 1 or not d.isdigit():
            return False
        current = str(self.state.reject_multiplier_input or "")
        new_value = (current + d).lstrip("0")
        self.state.reject_multiplier_input = new_value or ("0" if (current + d) else "")
        if self.state.reject_multiplier_input == "0":
            self.state.reject_multiplier_input = ""
        return True

    def _trim_reject_multiplier(self):
        self.state.reject_multiplier_input = str(self.state.reject_multiplier_input or "")[:-1]

    def _reject_multiplier_indicator_text(self) -> str:
        raw = str(self.state.reject_multiplier_input or "").strip()
        if not raw:
            return ""
        return f"Multiplier active: x{self._reject_multiplier_value()} (scan backspace to edit)"

    def _consume_reject_multiplier_if_inapplicable(self, raw_l: str):
        s = self.state
        if not str(s.reject_multiplier_input or "").strip():
            return
        if raw_l.startswith("num_") and raw_l[-1:].isdigit():
            return
        if raw_l == "backspace":
            return
        self._clear_reject_multiplier()

    def _update_product_parts_weight_indicator(self):
        if not hasattr(self, "jobPartsTable") or self.jobPartsTable is None:
            return
        part_rows = self._job_part_rows()
        row_count = int(self.jobPartsTable.rowCount() or 0)
        has_job = bool(str(self.state.job_code or "").strip())
        if row_count <= 0:
            return
        phase = (math.sin(time.time() * 5.2) + 1.0) * 0.5
        for row in range(row_count):
            item = self.jobPartsTable.item(row, 1)
            if item is None:
                continue
            txt = str(item.text() or "").strip()
            if not has_job or txt in ("", "-"):
                item.setBackground(QBrush(Qt.GlobalColor.transparent))
                item.setForeground(QBrush(QColor(239, 240, 242, 226)))
                continue
            part = part_rows[row] if row < len(part_rows) else {}
            info = self._resolve_part_qty_per_unit(part)
            if self._part_unit_kind(part) != "kg":
                item.setBackground(QBrush(Qt.GlobalColor.transparent))
                item.setForeground(QBrush(QColor(239, 240, 242, 226)))
            elif info.get("source") == "app" and not bool(self.state.external_average_weight_needs_refresh):
                item.setBackground(QBrush(QColor(34, 197, 94, 185)))
                item.setForeground(QBrush(QColor("#ecfdf5")))
            else:
                flash_alpha = int(90 + (95 * phase))
                item.setBackground(QBrush(QColor(248, 113, 113, flash_alpha)))
                item.setForeground(QBrush(QColor("#fff7ed")))

    def _apply_external_average_weight(self, average_grams: float, unit: str, sent_at: str = "", source: str = "app", sender: str = ""):
        grams = float(average_grams or 0.0)
        normalized_unit = str(unit or "g").strip() or "g"
        if grams <= 0:
            return
        kg_value = grams / 1000.0
        s = self.state
        s.external_average_weight_grams = grams
        s.external_average_weight_unit = normalized_unit
        s.external_average_weight_received_at = datetime.now(timezone.utc).isoformat()
        s.external_average_weight_sent_at = str(sent_at or "").strip() or None
        s.external_average_weight_source = str(source or "app").strip() or "app"
        s.external_average_weight_sender = str(sender or "").strip() or None
        s.external_average_weight_needs_refresh = False
        converted_packs = self._apply_weight_to_standard_pack_consumption(grams)
        converted_raw_logs = self._apply_weight_to_standard_raw_material_logs(grams)
        if converted_packs or converted_raw_logs:
            self.status.setText(
                f"Average weight received: {kg_value:.4f} kg. Updated {converted_packs} standard pack(s)."
            )
        else:
            self.status.setText(f"Average weight received from app: {kg_value:.4f} kg")
        self._refresh_ui()
        if s.machine_code:
            self._save_active_session_snapshot()
        self.push_event(
            {
                "type": "AVERAGE_WEIGHT_RECEIVED",
                "average_grams": grams,
                "average_kg": kg_value,
                "unit": normalized_unit,
                "sent_at": s.external_average_weight_sent_at,
                "source": s.external_average_weight_source,
                "sender": s.external_average_weight_sender,
                "received_at": s.external_average_weight_received_at,
            },
            f"AVERAGE WEIGHT {kg_value:.4f} kg",
        )

    def _apply_server_average_weight(self, machine_code: str, average_grams: float, unit: str, received_at: str, sent_at: str, source: str, sender: str):
        if str(self.state.machine_code or "").strip() != str(machine_code or "").strip():
            return
        if self.state.external_average_weight_needs_refresh:
            previous_received = self._parse_utc_iso_datetime(
                self.state.external_average_weight_received_at
            )
            incoming_received = self._parse_utc_iso_datetime(received_at)
            previous_sent = str(self.state.external_average_weight_sent_at or "").strip()
            incoming_sent = str(sent_at or "").strip()
            unchanged_sent = bool(previous_sent and incoming_sent == previous_sent)
            unchanged_received = bool(
                previous_received
                and incoming_received
                and incoming_received <= previous_received
            )
            if unchanged_received or (incoming_received is None and unchanged_sent):
                # Polling may continue returning the pre-PDR weight. Keep the
                # pending state until the server exposes a genuinely newer send.
                return
        identity = self._job_product_identity_from_payload(self.state.job_payload)
        current_product_id = str(identity.get("product_id") or "").strip()
        current_sku = str(identity.get("product_sku") or "").strip()
        # The server already validates product/SKU. This second check prevents a stale
        # poll from applying a result after this client changed jobs locally.
        if current_product_id or current_sku:
            self._apply_external_average_weight(average_grams, unit, sent_at, source or "server", sender)
            self.state.external_average_weight_received_at = str(received_at or "").strip() or self.state.external_average_weight_received_at
            if self.state.machine_code:
                self._save_active_session_snapshot()

    def _poll_server_average_weight(self):
        machine_code = str(self.state.machine_code or "").strip()
        if not machine_code:
            return
        with self._server_weight_poll_lock:
            if self._server_weight_poll_inflight:
                return
            self._server_weight_poll_inflight = True

        def _worker():
            try:
                server_url = str(self.client_config.get("server_url", SERVER_URL)).strip().rstrip("/")
                response = requests.get(
                    f"{server_url}/api/active-sessions",
                    params={"client_id": self._current_client_id(), "machine_code": machine_code},
                    headers={"Accept": "application/json"},
                    timeout=2.5,
                )
                if response.status_code == 200:
                    # A successful live poll proves the server is reachable.
                    # Do not leave production scanning in offline mode merely
                    # because the separate event queue is draining retries.
                    self._server_connection_ok = True
                    self._server_last_success_at = time.time()
                payload = response.json() if response.status_code == 200 else {}
                rows = payload.get("items") if isinstance(payload, dict) else []
                row = rows[0] if isinstance(rows, list) and rows and isinstance(rows[0], dict) else {}
                weight = row.get("external_average_weight_grams")
                received_at = str(row.get("external_average_weight_received_at") or "").strip()
                marker = f"{machine_code}|{received_at}|{weight}"
                if weight is not None and received_at and marker != self._last_server_weight_marker:
                    self._last_server_weight_marker = marker
                    self.server_average_weight_received.emit(
                        machine_code,
                        float(weight),
                        str(row.get("external_average_weight_unit") or "g"),
                        received_at,
                        str(row.get("external_average_weight_sent_at") or ""),
                        str(row.get("external_average_weight_source") or "server"),
                        str(row.get("external_average_weight_sender") or ""),
                    )
            except Exception:
                pass
            finally:
                with self._server_weight_poll_lock:
                    self._server_weight_poll_inflight = False

        threading.Thread(target=_worker, daemon=True).start()

    def _start_average_weight_server(self):
        if self._avg_weight_server is not None:
            return

        ui = self

        class AverageWeightHandler(BaseHTTPRequestHandler):
            def _send_json(self, status: int, payload: Dict[str, Any]):
                raw = json.dumps(payload).encode("utf-8")
                self.send_response(status)
                self.send_header("Content-Type", "application/json")
                self.send_header("Content-Length", str(len(raw)))
                self.end_headers()
                self.wfile.write(raw)

            def log_message(self, format: str, *args):
                return

            def do_POST(self):
                if self.path.rstrip("/") != AVERAGE_WEIGHT_API_ENDPOINT:
                    self._send_json(404, {"success": False, "message": "Not found"})
                    return
                try:
                    content_length = int(self.headers.get("Content-Length", "0") or 0)
                except Exception:
                    content_length = 0
                body = self.rfile.read(max(0, content_length))
                try:
                    payload = json.loads(body.decode("utf-8") if body else "{}")
                except Exception:
                    self._send_json(400, {"success": False, "message": "Invalid JSON"})
                    return
                if not isinstance(payload, dict):
                    self._send_json(400, {"success": False, "message": "JSON body must be an object"})
                    return
                try:
                    average_grams = float(payload.get("average_grams"))
                except Exception:
                    self._send_json(400, {"success": False, "message": "average_grams must be numeric"})
                    return
                unit = str(payload.get("unit") or "").strip() or "g"
                sent_at = str(payload.get("sent_at") or payload.get("sent_at_utc") or "").strip()
                source = str(payload.get("source") or "app").strip() or "app"
                sender = str(payload.get("sender") or payload.get("sent_by") or "").strip()
                if average_grams <= 0:
                    self._send_json(400, {"success": False, "message": "average_grams must be greater than zero"})
                    return
                ui.average_weight_received.emit(average_grams, unit, sent_at, source, sender)
                self._send_json(200, {"success": True, "message": "Average weight received"})

        try:
            server = ThreadingHTTPServer((AVERAGE_WEIGHT_API_HOST, AVERAGE_WEIGHT_API_PORT), AverageWeightHandler)
            server.daemon_threads = True
            self._avg_weight_server = server
            self._avg_weight_server_thread = threading.Thread(target=server.serve_forever, daemon=True)
            self._avg_weight_server_thread.start()
            self._avg_weight_server_error = None
            print(f"[AverageWeightAPI] Listening on http://{AVERAGE_WEIGHT_API_HOST}:{AVERAGE_WEIGHT_API_PORT}{AVERAGE_WEIGHT_API_ENDPOINT}")
        except Exception as e:
            self._avg_weight_server = None
            self._avg_weight_server_thread = None
            self._avg_weight_server_error = str(e)
            print(f"[AverageWeightAPI] Failed to start: {e}")

    def _shutdown_average_weight_server(self):
        server = self._avg_weight_server
        self._avg_weight_server = None
        if server is None:
            return
        try:
            server.shutdown()
        except Exception:
            pass
        try:
            server.server_close()
        except Exception:
            pass

    def _make_finish_summary_table(self, title: str, headers: List[str]) -> QFrame:
        section = QFrame()
        section.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Expanding)
        section.setStyleSheet(
            "QFrame {"
            "background: qlineargradient(x1:0, y1:0, x2:0, y2:1, stop:0 rgba(103,107,115,220), stop:1 rgba(56,59,66,230));"
            "border: 1px solid rgba(148,163,184,0.26); border-radius: 10px; }"
            "QLabel { color: #f8fafc; font-size: 18px; font-weight: 900; background: transparent; border: none; }"
        )
        section.setLayout(QVBoxLayout())
        section.layout().setContentsMargins(6, 6, 6, 6)
        section.layout().setSpacing(4)
        title_lbl = QLabel(title)
        table = QFrame()
        table.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Expanding)
        table.setStyleSheet(
            "QFrame { background: rgba(15,23,42,0.32); border: none; border-radius: 10px; }"
            "QLabel[role='header'] { background: rgba(71,85,105,0.96); color: #f8fafc; font-size: 14px; font-weight: 900; padding: 5px 6px; }"
            "QLabel[role='cell'] { color: #f8fafc; font-size: 15px; font-weight: 800; padding: 4px 7px; border-bottom: 1px solid rgba(148,163,184,0.20); }"
        )
        rows_host = QWidget(table)
        rows_layout = QGridLayout()
        rows_layout.setContentsMargins(0, 0, 0, 0)
        rows_layout.setHorizontalSpacing(0)
        rows_layout.setVerticalSpacing(0)
        rows_host.setLayout(rows_layout)
        table.setLayout(QVBoxLayout())
        table.layout().setContentsMargins(0, 0, 0, 0)
        table.layout().setSpacing(0)
        table.layout().addWidget(rows_host)
        table._finish_headers = list(headers or ["Entry"])
        table._finish_rows_host = rows_host
        table._finish_rows_layout = rows_layout
        table._finish_section = section
        table._finish_title_label = title_lbl
        table._finish_stretch_rows = True
        section.layout().addWidget(title_lbl)
        section.layout().addWidget(table, 1)
        return table

    def _set_finish_summary_table_rows(self, table: Optional[QFrame], rows: List[List[str]]):
        if table is None:
            return
        layout = getattr(table, "_finish_rows_layout", None)
        headers = list(getattr(table, "_finish_headers", ["Entry"]) or ["Entry"])
        if layout is None:
            return
        while layout.count():
            item = layout.takeAt(0)
            widget = item.widget()
            if widget is not None:
                widget.deleteLater()
        col_count = max(1, len(headers))
        clean_rows = rows or [["-"] * col_count]
        show_header = not (col_count == 1 and str(headers[0]).strip().lower() == "entry")
        stretch_rows = bool(getattr(table, "_finish_stretch_rows", True))
        grid_row = 0
        if show_header:
            for c, header in enumerate(headers):
                lbl = QLabel(str(header))
                lbl.setProperty("role", "header")
                lbl.setAlignment(Qt.AlignmentFlag.AlignCenter)
                if stretch_rows:
                    lbl.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Expanding)
                else:
                    lbl.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Fixed)
                    lbl.setMinimumHeight(34)
                    lbl.setMaximumHeight(34)
                layout.addWidget(lbl, grid_row, c)
            grid_row += 1
        for row_vals in clean_rows:
            values = list(row_vals or [])
            while len(values) < col_count:
                values.append("-")
            for c in range(col_count):
                lbl = QLabel(str(values[c]))
                lbl.setProperty("role", "cell")
                lbl.setWordWrap(True)
                if col_count == 1 or c == 0:
                    lbl.setAlignment(Qt.AlignmentFlag.AlignLeft | Qt.AlignmentFlag.AlignVCenter)
                else:
                    lbl.setAlignment(Qt.AlignmentFlag.AlignCenter)
                if stretch_rows:
                    lbl.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Expanding)
                else:
                    lbl.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Fixed)
                    lbl.setMinimumHeight(52)
                    lbl.setMaximumHeight(58)
                layout.addWidget(lbl, grid_row, c)
            grid_row += 1
        for c in range(col_count):
            layout.setColumnStretch(c, 1)
        for r in range(grid_row):
            layout.setRowStretch(r, 0 if (show_header and r == 0) or not stretch_rows else 1)
        row_h = 30 if stretch_rows else 54
        header_h = 34 if show_header else 0
        target_h = max(30, header_h + (len(clean_rows) * row_h) + 3)
        rows_host = getattr(table, "_finish_rows_host", None)
        if rows_host is not None:
            rows_host.setMinimumHeight(target_h)
            if stretch_rows:
                rows_host.setMaximumHeight(16777215)
                rows_host.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Expanding)
                table.layout().setAlignment(rows_host, Qt.AlignmentFlag.AlignTop)
            else:
                rows_host.setMaximumHeight(target_h)
                rows_host.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Fixed)
                table.layout().setAlignment(rows_host, Qt.AlignmentFlag.AlignTop)
        table.setMinimumHeight(target_h)
        table.setMaximumHeight(16777215)
        section = getattr(table, "_finish_section", None)
        if section is not None:
            title_h = 26
            margin_h = 14
            section_h = target_h + title_h + margin_h
            section.setMinimumHeight(section_h)
            section.setMaximumHeight(16777215)
            section.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Expanding)

    def _stretch_finish_summary_table(self, table: Optional[QFrame], section_height: int):
        if table is None:
            return
        section = getattr(table, "_finish_section", None)
        if section is None:
            return
        section_h = max(72, int(section_height or 0))
        table_h = max(32, section_h - 38)
        table.setMinimumHeight(table_h)
        table.setMaximumHeight(16777215)
        table.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Expanding)
        section.setMinimumHeight(section_h)
        section.setMaximumHeight(16777215)
        section.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Expanding)

    def _finish_review_available_content_height(self) -> int:
        stack_h = 0
        if hasattr(self, "finishSummaryStack") and self.finishSummaryStack is not None:
            stack_h = int(self.finishSummaryStack.height() or 0)
        if stack_h <= 80 and hasattr(self, "finishSummaryScroll") and self.finishSummaryScroll is not None:
            stack_h = int(self.finishSummaryScroll.height() or 0)
        if stack_h <= 80 and hasattr(self, "finishOverlay") and self.finishOverlay is not None:
            stack_h = int(self.finishOverlay.height() or 0) - 118
        return max(640, stack_h - 4)

    def _extract_job_payload_context(self, payload: Dict[str, Any]) -> Dict[str, Any]:
        data_obj = payload.get("data") if isinstance(payload.get("data"), dict) else {}
        job = data_obj.get("job") if isinstance(data_obj.get("job"), dict) else {}
        job_details = data_obj.get("job_details") if isinstance(data_obj.get("job_details"), dict) else {}
        if not job and isinstance(payload.get("job"), dict):
            job = payload.get("job") or {}
        if not job_details and isinstance(payload.get("job_details"), dict):
            job_details = payload.get("job_details") or {}
        parts = []
        if isinstance(data_obj.get("parts"), list):
            parts = [r for r in data_obj.get("parts") or [] if isinstance(r, dict)]
        elif isinstance(job_details.get("parts"), list):
            parts = [r for r in job_details.get("parts") or [] if isinstance(r, dict)]
        elif isinstance(job_details.get("part_ids"), list):
            parts = [r for r in job_details.get("part_ids") or [] if isinstance(r, dict)]
        elif isinstance(data_obj.get("part_ids"), list):
            parts = [r for r in data_obj.get("part_ids") or [] if isinstance(r, dict)]
        elif isinstance(payload.get("part_ids"), list):
            parts = [r for r in payload.get("part_ids") or [] if isinstance(r, dict)]
        return {"job": job, "job_details": job_details, "parts": parts}

    def _job_product_identity_from_payload(self, payload: Optional[Dict[str, Any]]) -> Dict[str, str]:
        src = payload if isinstance(payload, dict) else {}
        ctx = self._extract_job_payload_context(src)
        candidates = [src, ctx.get("job_details"), ctx.get("job")]
        product_id = ""
        product_sku = ""
        product_name = ""
        for row in candidates:
            if not isinstance(row, dict):
                continue
            if not product_id:
                product_id = str(
                    row.get("product_id")
                    or row.get("product")
                    or row.get("item_id")
                    or ""
                ).strip()
            if not product_sku:
                product_sku = str(
                    row.get("product_sku")
                    or row.get("sku")
                    or row.get("item_sku")
                    or ""
                ).strip()
            if not product_name:
                product_name = str(
                    row.get("product_name")
                    or row.get("name")
                    or row.get("item_name")
                    or ""
                ).strip()
        if product_id and not product_sku:
            product_sku = self._lookup_product_sku(product_id)
        if product_id and not product_name:
            product_name = self._lookup_product_name(product_id)
        if not product_sku:
            job = ctx.get("job") if isinstance(ctx.get("job"), dict) else {}
            product_sku = str(
                src.get("product_sku")
                or src.get("sku")
                or src.get("job_name")
                or src.get("job_code")
                or job.get("product_sku")
                or job.get("sku")
                or job.get("ref_no")
                or ""
            ).strip()
        return {
            "product_id": product_id,
            "product_sku": product_sku,
            "product_name": product_name,
        }

    def _normalized_identity_text(self, value: Any) -> str:
        return re.sub(r"[^A-Z0-9]+", "", str(value or "").strip().upper())

    def _job_change_identity_from_payload(self, payload: Optional[Dict[str, Any]]) -> Dict[str, str]:
        src = payload if isinstance(payload, dict) else {}
        ctx = self._extract_job_payload_context(src)
        job = ctx.get("job") if isinstance(ctx.get("job"), dict) else {}
        details = ctx.get("job_details") if isinstance(ctx.get("job_details"), dict) else {}
        product = self._job_product_identity_from_payload(src)
        color = (
            details.get("color")
            or details.get("colour")
            or details.get("custom_06")
            or job.get("color")
            or job.get("colour")
            or job.get("custom_06")
            or src.get("color")
            or src.get("colour")
            or ""
        )
        mold = (
            details.get("mold")
            or details.get("mold_no")
            or details.get("mould")
            or details.get("custom_05")
            or job.get("mold")
            or job.get("mold_no")
            or job.get("mould")
            or job.get("custom_05")
            or src.get("mold")
            or ""
        )
        return {
            "product_id": str(product.get("product_id") or "").strip(),
            "product_sku": str(product.get("product_sku") or "").strip(),
            "product_name": str(product.get("product_name") or "").strip(),
            "color": str(color or "").strip(),
            "mold": str(mold or "").strip(),
        }

    def _classify_job_change_reason(self, current_payload: Optional[Dict[str, Any]], new_payload: Optional[Dict[str, Any]], requested_reason: str = "COLOR_CHANGE") -> Dict[str, Any]:
        requested = str(requested_reason or "COLOR_CHANGE").strip().upper()
        if requested not in ("COLOR_CHANGE", "MOLD_CHANGE"):
            requested = "COLOR_CHANGE"
        current_identity = self._job_change_identity_from_payload(current_payload)
        new_identity = self._job_change_identity_from_payload(new_payload)
        same_product = False
        for key in ("product_id", "product_sku", "product_name"):
            left = self._normalized_identity_text(current_identity.get(key))
            right = self._normalized_identity_text(new_identity.get(key))
            if left and right and left == right:
                same_product = True
                break
        current_color = self._normalized_identity_text(current_identity.get("color"))
        new_color = self._normalized_identity_text(new_identity.get("color"))
        color_changed = bool(current_color and new_color and current_color != new_color)
        reason = "COLOR_CHANGE" if same_product else "MOLD_CHANGE"
        if same_product and not color_changed:
            reason = "COLOR_CHANGE"
        return {
            "reason": reason,
            "requested_reason": requested,
            "same_product": same_product,
            "color_changed": color_changed,
            "current": current_identity,
            "new": new_identity,
        }

    def _finish_shift_row_key(self, row: Dict[str, Any]) -> str:
        return "|".join([
            str(row.get("record_type") or "").strip().upper(),
            str(row.get("client_id") or "").strip(),
            str(row.get("machine_code") or "").strip(),
            str(row.get("job_code") or "").strip(),
            str(row.get("operator_id") or "").strip(),
            str(row.get("shift_index") or "").strip(),
            str(row.get("finished_at_utc") or row.get("ended_at_utc") or "").strip(),
        ])

    def _server_finished_job_key(self, row: Dict[str, Any]) -> str:
        return "|".join([
            str(row.get("finished_at_utc", "")),
            str(row.get("machine_code", "")),
            str(row.get("job_code", "")),
            str(row.get("operator_id", "")),
            str(row.get("pack_count", "")),
            str(row.get("good_total", "")),
            str(row.get("butal_total", "")),
            str(row.get("reject_total", "")),
        ])

    def _approve_local_finished_shift(self, shift_payload: Dict[str, Any], reviewer: Dict[str, Any], remarks: str) -> bool:
        key = self._finish_shift_row_key(shift_payload)
        rows = _load_finish_shift_json()
        updated = False
        now_utc = datetime.now(timezone.utc).isoformat()
        for idx, row in enumerate(rows):
            if not isinstance(row, dict):
                continue
            if self._finish_shift_row_key(row) != key:
                continue
            row = dict(row)
            row["approved_by"] = reviewer.get("name")
            row["approved_by_code"] = reviewer.get("code")
            row["approved_by_role"] = reviewer.get("role")
            row["approved_remarks"] = remarks
            row["approved_at_utc"] = now_utc
            row["review_status"] = REVIEW_STATUS_APPROVED
            history = list(row.get("review_history") or [])
            history.append({
                "action": "APPROVE",
                "remarks": remarks,
                "actor_name": reviewer.get("name"),
                "actor_code": reviewer.get("code"),
                "actor_role": reviewer.get("role"),
                "timestamp_utc": now_utc,
            })
            row["review_history"] = history
            rows[idx] = row
            shift_payload.update(row)
            updated = True
            break
        if not updated:
            return False
        return _save_finish_shift_json(rows)

    def _approve_server_finished_shift(self, shift_payload: Dict[str, Any], reviewer_badge: str, remarks: str):
        try:
            resp = self._request_with_ui_events(
                requests.post,
                f"{str(self.client_config.get('server_url', SERVER_URL)).rstrip('/')}/api/finished-jobs/review",
                json={
                    "job_key": self._server_finished_job_key(shift_payload),
                    "action": "approve",
                    "remarks": remarks,
                    "reviewer_badge": reviewer_badge,
                },
                timeout=4.5,
            )
            return resp.ok
        except Exception:
            return False

