        self.finishSummaryOverviewSection.setMaximumHeight(overview_h)
        self.finishSummaryCards["Machine"].setText(self._safe_text(shift_payload.get("machine_name") or shift_payload.get("machine_code")))
        pending_shift_jobs = []
